INSERT INTO `antipattern_info` VALUES (75, 'Poor Restful Api Design', 'Inadequate Use of APIs', 'It refers to the issue of utilizing RESTful-style APIs in microservice architectures that are poorly designed or lack coherence. For instance, the APIs have inconsistent naming conventions, making them difficult to comprehend. The utilization of HTTP request methods (GET, POST, PUT, DELETE, etc.) to represent various resource operations is illogical, and these methods are inconsistent with the specific business logic. API versions are often misused or managed in an unreasonable manner, posing challenges for backward compatibility. Additionally, the APIs fail to offer appropriate error status codes, error messages, or error-handling mechanisms for managing errors and exceptions, thereby impeding the client\'s ability to accurately identify and handle error conditions.', 'Identification of naming conformity using camel case conventions and other methods. Verification of request method consistency with business logic using rule-based approaches. Identification of API version problems using regular expression matching techniques.', 'Inappropriate utilization of APIs, disregard for naming conventions, failure to adhere to verb usage in RESTful APIs, and inadequate API version control. ', 'Inappropriate utilization of APIs, disregard for naming conventions, failure to adhere to verb usage in RESTful APIs, and inadequate API version control. ', 'Violating RESTful API design conventions, an item is added to the cart using a POST request instead of a PUT request.', '[\"@article{de2021identifying,  title={Identifying architectural technical debt, principal, and interest in microservices: A multiple-case study},  author={de Toledo, Saulo S and Martini, Antonio and Sj{\\\\o}berg, Dag IK},  journal={Journal of Systems and Software},  volume={177},  pages={110968},  year={2021},  publisher={Elsevier}}\",\"@article{de2022accumulation,  title={Accumulation and prioritization of architectural debt in three companies migrating to microservices},  author={De Toledo, Saulo Soares and Martini, Antonio and Nguyen, Phu H and Sj{\\\\o}berg, Dag IK},  journal={IEEE Access},  volume={10},  pages={37422--37445},  year={2022},  publisher={IEEE}}\"]', 'Internal Design', 'API design', 14, 0);
INSERT INTO `antipattern_info` VALUES (76, 'CRUDY Interface', NULL, 'The service is encouraged to adopt an RPC-like behavior by implementing CRUD-type operations, such as create_A(), read_B(). However, this approach may result in the service resembling a gossip service or a nano-service, and the direct exposure of CRUD operations in the interface name introduces certain risks.', 'Establish rules to identify interface naming patterns and determine if they correspond to CRUD operations.', 'The rapid proliferation of interfaces can lead to a decrease in Maintainability, an increase in the complexity and effort of testing, and a reduction in Testability. Additionally, the use of CRUD interface naming can expose sensitive operations, compromising the system\'s security . Furthermore, it becomes challenging to modify the data model, thereby limiting Adaptability.', 'The reasons behind these issues include an excessive emphasis on data manipulation, a lack of domain-driven design thinking, and a failure to consider the system as a whole.', 'A user creation interface named create_User() is utilized.', '[\"@inproceedings{palma2015study,  title={A study on the taxonomy of service antipatterns},  author={Palma, Francis and Mohay, Naouel},  booktitle={2015 IEEE 2nd International Workshop on Patterns Promotion and Anti-patterns Prevention (PPAP)},  pages={5--8},  year={2015},  organization={IEEE}}\",\"@inproceedings{wang2017value,   title={On the value of quality of service attributes for detecting bad design practices},   author={Wang, Hanzhang and Kessentini, Marouane and Hassouna, Taghreed and Ouni, Ali},   booktitle={2017 IEEE International Conference on Web Services (ICWS)},   pages={341--348},   year={2017},   organization={IEEE} }\"]', 'Internal Design', 'API design', 5, 0);
INSERT INTO `antipattern_info` VALUES (77, 'Ambiguous Service', '[\"Ambiguous Name\"，\"Ambiguous Interfface\"]', 'Service or interface names that are overly generic pose challenges in discerning the extent of functional responsibilities.', 'Establish rules for detecting service (interface) naming patterns.', 'This will diminish modularity.', ' Ambiguous naming arises from a lack of clearly defined requirements.', 'Initially, the microservice named ProcessService was utilized for processing order information. However, as the business expanded, additional functions related to logistics information were incorporated without clearly defining the functional boundaries.', '[\"@inproceedings{palma2015study,  title={A study on the taxonomy of service antipatterns},  author={Palma, Francis and Mohay, Naouel},  booktitle={2015 IEEE 2nd International Workshop on Patterns Promotion and Anti-patterns Prevention (PPAP)},  pages={5--8},  year={2015},  organization={IEEE}}\",\"@inproceedings{azadi2019architectural,  title={Architectural smells detected by tools: a catalogue proposal},  author={Azadi, Umberto and Fontana, Francesca Arcelli and Taibi, Davide},  booktitle={2019 IEEE/ACM International Conference on Technical Debt (TechDebt)},  pages={88--97},  year={2019},  organization={IEEE}}\",\"@inproceedings{palma2014specification,   title={Specification and detection of SOA antipatterns in web services},   author={Palma, Francis and Moha, Naouel and Tremblay, Guy and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   booktitle={Software Architecture: 8th European Conference, ECSA 2014, Vienna, Austria, August 25-29, 2014. Proceedings 8},   pages={58--73},   year={2014},   organization={Springer} }\",\"@article{coscia2014refactoring,   title={Refactoring code-first Web Services for early avoiding WSDL anti-patterns: Approach and comprehensive assessment},   author={Coscia, Jos{\\\\\'e} Luis Ordiales and Mateos, Cristian and Crasso, Marco and Zunino, Alejandro},   journal={Science of Computer Programming},   volume={89},   pages={374--407},   year={2014},   publisher={Elsevier} }\",\"  @article{tummalapalli2022detection,   title={Detection of web service anti-patterns using weighted extreme learning machine},   author={Tummalapalli, Sahithi and Kumar, Lov and Neti, Lalita Bhanu Murthy and Krishna, Aneesh},   journal={Computer Standards \\\\& Interfaces},   volume={82},   pages={103621},   year={2022},   publisher={Elsevier} }\",\"@inproceedings{wang2017value,   title={On the value of quality of service attributes for detecting bad design practices},   author={Wang, Hanzhang and Kessentini, Marouane and Hassouna, Taghreed and Ouni, Ali},   booktitle={2017 IEEE International Conference on Web Services (ICWS)},   pages={341--348},   year={2017},   organization={IEEE} }\"]', 'Internal Design', 'API design', 1, 0);
INSERT INTO `antipattern_info` VALUES (78, 'Bloated Service', NULL, 'The service exhibits a large interface with an excessive number of parameters, and it carries out diverse and heterogeneous operations within this interface, resulting in low cohesion between these operations.', 'Formulate rules to extract metrics such as interface size, parameter count, and operation heterogeneity in order to make determinations.', 'This leads to diminished Maintainability, Reusability, and Testability. Additionally, the low cohesion between operations adversely affects Modularity.', 'These issues arise from a lack of domain-driven design and unreasonable interface design.', 'The ProductService microservice features an API interface named searchProducts, which encompasses 8 parameters (e.g., keyword, category, etc.) and conducts heterogeneous operations in conjunction with other interfaces.', '[\"@inproceedings{palma2015study,  title={A study on the taxonomy of service antipatterns},  author={Palma, Francis and Mohay, Naouel},  booktitle={2015 IEEE 2nd International Workshop on Patterns Promotion and Anti-patterns Prevention (PPAP)},  pages={5--8},  year={2015},  organization={IEEE}}\",\"  @inproceedings{palma2014specification,   title={Specification and detection of SOA antipatterns in web services},   author={Palma, Francis and Moha, Naouel and Tremblay, Guy and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   booktitle={Software Architecture: 8th European Conference, ECSA 2014, Vienna, Austria, August 25-29, 2014. Proceedings 8},   pages={58--73},   year={2014},   organization={Springer} }\",\"@inproceedings{palma2014investigating,   title={Investigating the change-proneness of service patterns and antipatterns},   author={Palma, Francis and An, Le and Khomh, Foutse and Moha, Naouel and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   booktitle={2014 IEEE 7th International Conference on Service-Oriented Computing and Applications},   pages={1--8},   year={2014},   organization={IEEE} }\"]', 'Internal Design', 'API design', 5, 0);
INSERT INTO `antipattern_info` VALUES (79, 'Whatever Types', 'Ignoring MIME Types', 'The server disregards the client\'s requirements and capabilities when delivering resources, consistently providing them in a single format.', 'Analyze the returned response from the microservice to determine if it is consistently stored in a single Content-Type.', 'This leads to a single representation of the resource, thereby diminishing its Reliability.', 'This stems from disregarding the client\'s needs and processing capabilities.', 'Regardless of the client\'s requested resource type, every API of ProductService consistently returns a response with a Content-Type of application/json.', '[\"@article{palma2018unidosa,   title={UniDoSA: the unified specification and detection of service antipatterns},   author={Palma, Francis and Moha, Naouel and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   journal={IEEE Transactions on Software Engineering},   volume={45},   number={10},   pages={1024--1053},   year={2018},   publisher={IEEE} }\",\"@article{coscia2014refactoring,   title={Refactoring code-first Web Services for early avoiding WSDL anti-patterns: Approach and comprehensive assessment},   author={Coscia, Jos{\\\\\'e} Luis Ordiales and Mateos, Cristian and Crasso, Marco and Zunino, Alejandro},   journal={Science of Computer Programming},   volume={89},   pages={374--407},   year={2014},   publisher={Elsevier} }\"]', 'Internal Design', 'API design', 4, 0);
INSERT INTO `antipattern_info` VALUES (80, 'No API Versioning', NULL, 'This indicates that the URI of the API interface does not contain explicitly specified semantic version information.', 'Develop a regular expression that matches the semantic version of the API, and subsequently extract and analyze the complete URL of the API to identify the presence of semantic versioning.', ' The lack of semantic version information hinders the coexistence of different service versions, thereby impacting analysability and diminishing modifiability.', 'This arises from the failure to consider backward compatibility.', 'The GET method is used to request /api/travelservice/routes/{tripId}, which retrieves trip information based on the tripId. However, this URI does not include the necessary semantic versioning information for the API.', '[\"@article{taibi2018definition,  title={On the definition of microservice bad smells},  author={Taibi, Davide and Lenarduzzi, Valentina},  journal={IEEE software},  volume={35},  number={3},  pages={56--62},  year={2018},  publisher={IEEE}}\",\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"  @inproceedings{pulnil2022microservices,   title={A microservices quality model based on microservices anti-patterns},   author={Pulnil, Sermsook and Senivongse, Twittie},   booktitle={2022 19th International Joint Conference on Computer Science and Software Engineering (JCSSE)},   pages={1--6},   year={2022},   organization={IEEE}}\",\"@article{walker2020automated,   title={Automated code-smell detection in microservices through static analysis: A case study},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   journal={Applied Sciences},   volume={10},   number={21},   pages={7800},   year={2020},   publisher={MDPI} }\",\"@inproceedings{walker2021automated,   title={Automated microservice code-smell detection},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   booktitle={Information Science and Applications: Proceedings of ICISA 2020},   pages={211--221},   year={2021},   organization={Springer} }\",\"  @inproceedings{schirgi2021quality,   title={Quality assurance for microservice architectures},   author={Schirgi, Thomas and Brenner, Eugen},   booktitle={2021 IEEE 12th International Conference on Software Engineering and Service Science (ICSESS)},   pages={76--80},   year={2021},   organization={IEEE} }\"]', 'Internal Design', 'API design', 2, 0);
INSERT INTO `antipattern_info` VALUES (81, 'Unstable API', NULL, 'Unstable APIs are susceptible to frequent changes and errors throughout the evolution of microservices.', 'Determined by analyzing the revision history.', 'The frequent modification of APIs, coupled with high error rates, diminishes both Reliability and Modifiability.', 'This arises from both immature design and changes in requirements.', ' In the initial release, certain endpoints of the API may have contained security vulnerabilities, potentially allowing unauthorized access to sensitive information. To mitigate this issue, the development team modified the API to implement more stringent authentication and authorization mechanisms. However, due to the unstable design of the API, the team discovered additional security vulnerabilities in subsequent versions, necessitating further modifications to the API. These frequent modifications not only consumed development resources but also resulted in an unstable API that heightened the risk of errors.', '[\"@inproceedings{fang2023identifying,title={Identifying Anti-Patterns in Distributed Systems With Heterogeneous Dependencies},author={Fang, Hongzhou and Cai, Yuanfang and Kazman, Rick and Lefever, Jason},booktitle={2023 IEEE 20th International Conference on Software Architecture Companion (ICSA-C)},pages={116--120},year={2023},organization={IEEE}}\"]', 'Internal Design', 'API design', 5, 0);
INSERT INTO `antipattern_info` VALUES (82, 'Crossing API', NULL, 'The API exhibits high fan-in and fan-out, making it susceptible to frequent modifications and prone to errors.', 'Extract the fan-in and fan-out indicators of the API and combine them with the modification history and system logs to make a comprehensive assessment.', 'The ease of modification and proneness to errors result in low reliability and modifiability.', 'This is attributed to improper module division and changes in requirements.', 'Consider an e-commerce system that includes an API for an order service, which is utilized by various microservices such as a user service, a payment service, and an inventory service. Additionally, the API itself invokes other services to fulfill different stages of order processing. Throughout the system\'s evolution, the API for the order service frequently requires modifications and adaptations due to changing requirements. Given its high fan-in and fan-out, these modifications often involve multiple callers and callees. For instance, when the Order Service needs to introduce a new order state, it may necessitate adjustments to the processing logic of the caller and ensuring that the callee can correctly handle the new state. The frequent modifications and interactions across multiple components escalate the complexity and challenges in maintaining the system, thereby diminishing its maintainability and fault tolerance.', '[\"@inproceedings{fang2023identifying,title={Identifying Anti-Patterns in Distributed Systems With Heterogeneous Dependencies},author={Fang, Hongzhou and Cai, Yuanfang and Kazman, Rick and Lefever, Jason},booktitle={2023 IEEE 20th International Conference on Software Architecture Companion (ICSA-C)},pages={116--120},year={2023},organization={IEEE}}\"]', 'Internal Design', 'API design', 5, 0);
INSERT INTO `antipattern_info` VALUES (83, 'Dismiss Documentation', NULL, 'The lack of comprehensive documentation that includes detailed descriptions of APIs indicates a tendency to trivialize or neglect the importance of documentation.', 'Detection involves scanning source packages for files in the md format.', 'Insufficient documentation for API Description has a negative impact on the system\'s availability and maintainability. Moreover, the absence of accurate documentation as a guide hinders the system\'s adaptability when adapting to new requirements.', 'This is attributed to a lack of awareness regarding the importance of documentation and disregard for its value.', 'For example, there is a lack of documentation for Description of APIs related to food and food orders in the food service.', '[\"@article{balalaie2018microservices,   title={Microservices migration patterns},   author={Balalaie, Armin and Heydarnoori, Abbas and Jamshidi, Pooyan and Tamburri, Damian A and Lynn, Theo},   journal={Software: Practice and Experience},   volume={48},   number={11},   pages={2019--2042},   year={2018},   publisher={Wiley Online Library}}\"]', 'Internal Design', 'API design', 7, 0);
INSERT INTO `antipattern_info` VALUES (84, 'Low Cohesive Operations', NULL, 'Developers often consolidate low cohesion operations within a single service, resulting in an accumulation of excessive code where each operation functions independently and performs unrelated tasks.', 'Determination based on the functional relationship between the different methods.', 'Low cohesion operations tend to cluster together, resulting in a reduction of modularity.', 'The lack of clear definition of the functional scope of the service during the functional design phase is the underlying cause.', 'For instance, in the context of a financial service, if there is a method dedicated to sending email notifications, it would be considered a low cohesion operation. The functionality for sending emails should ideally be part of a specialized notification service or mail service, separate from the finance service.', '[\"@inproceedings{palma2015study,  title={A study on the taxonomy of service antipatterns},  author={Palma, Francis and Mohay, Naouel},  booktitle={2015 IEEE 2nd International Workshop on Patterns Promotion and Anti-patterns Prevention (PPAP)},  pages={5--8},  year={2015},  organization={IEEE}}\",\"@inproceedings{palma2014specification,   title={Specification and detection of SOA antipatterns in web services},   author={Palma, Francis and Moha, Naouel and Tremblay, Guy and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   booktitle={Software Architecture: 8th European Conference, ECSA 2014, Vienna, Austria, August 25-29, 2014. Proceedings 8},   pages={58--73},   year={2014},   organization={Springer} }\",\"  @article{coscia2014refactoring,   title={Refactoring code-first Web Services for early avoiding WSDL anti-patterns: Approach and comprehensive assessment},   author={Coscia, Jos{\\\\\'e} Luis Ordiales and Mateos, Cristian and Crasso, Marco and Zunino, Alejandro},   journal={Science of Computer Programming},   volume={89},   pages={374--407},   year={2014},   publisher={Elsevier}}\"]', 'Internal Design', 'Method Design', 1, 0);
INSERT INTO `antipattern_info` VALUES (85, 'Stovepipe Service', NULL, 'It refers to a service that contains a significant number of private or protected methods primarily dedicated to utility functionality, such as logging, rather than the main operational goal.', 'It involves a combined assessment of access modifiers and method functionality.', 'This results in heightened code complexity and diminished maintainability. Furthermore, the overall structure and functionality of the service become challenging to comprehend, impeding learnability. Additionally, it becomes difficult to fulfill the expansion requirements of the system, thus limiting adaptability.', 'The absence of clear definition and separation of concerns during service design leads to the mixing of utility functions unrelated to the core operational goals.', 'For instance, in the order service code, there is a significant presence of private or protected methods dedicated to utility functions, such as logging the order creation process and sending notifications like email or SMS.', '[\"@inproceedings{palma2015study,  title={A study on the taxonomy of service antipatterns},  author={Palma, Francis and Mohay, Naouel},  booktitle={2015 IEEE 2nd International Workshop on Patterns Promotion and Anti-patterns Prevention (PPAP)},  pages={5--8},  year={2015},  organization={IEEE}}\"]', 'Internal Design', 'Method Design', 7, 0);
INSERT INTO `antipattern_info` VALUES (86, 'Data Service', 'Data coupling', 'It refers to a service primarily composed of accessor methods (e.g., getter/setter) characterized by high data cohesion. Its methods primarily handle small and basic types of parameters. Due to the absence of business logic, these services often serve other services.', 'The detection process involves extracting the method names within the service and formulating rules to assess them.', 'Modifying or adjusting these methods may require altering a significant number of calling codes simultaneously, resulting in diminished adaptability and maintainability. This can also introduce errors more easily and reduce the fault tolerance of the system.', 'This is primarily due to an excessive focus on data operations, resulting in a lack of encapsulation of domain logic.', 'For example, CustomerServiceImpl is a data service class encompassing private data fields (e.g., customerId, customerName, age, and address) and accessor methods (i.e., getter/setter) for accessing and modifying these fields. This data service class primarily focuses on data manipulation and lacks extensive business logic. It resembles more of a basic data container than a service class with robust functionality and domain logic.', '[\"@inproceedings{palma2015study,  title={A study on the taxonomy of service antipatterns},  author={Palma, Francis and Mohay, Naouel},  booktitle={2015 IEEE 2nd International Workshop on Patterns Promotion and Anti-patterns Prevention (PPAP)},  pages={5--8},  year={2015},  organization={IEEE}}\",\"  @article{tummalapalli2022detection,   title={Detection of web service anti-patterns using weighted extreme learning machine},   author={Tummalapalli, Sahithi and Kumar, Lov and Neti, Lalita Bhanu Murthy and Krishna, Aneesh},   journal={Computer Standards \\\\& Interfaces},   volume={82},   pages={103621},   year={2022},   publisher={Elsevier} }\",\"@inproceedings{fang2023identifying,   title={Identifying Anti-Patterns in Distributed Systems With Heterogeneous Dependencies},   author={Fang, Hongzhou and Cai, Yuanfang and Kazman, Rick and Lefever, Jason},   booktitle={2023 IEEE 20th International Conference on Software Architecture Companion (ICSA-C)},   pages={116--120},   year={2023},   organization={IEEE} }\",\"@inproceedings{wang2017value,   title={On the value of quality of service attributes for detecting bad design practices},   author={Wang, Hanzhang and Kessentini, Marouane and Hassouna, Taghreed and Ouni, Ali},   booktitle={2017 IEEE International Conference on Web Services (ICWS)},   pages={341--348},   year={2017},   organization={IEEE} }\"]', 'Internal Design', 'Method Design', 7, 0);
INSERT INTO `antipattern_info` VALUES (87, 'Nano Microservice', '[\"Excessive number of small products\"，\"Fine grained web service\", \"Tiny service\"]', 'This term refers to highly streamlined microservices, indicating that the microservice\'s granularity is excessively fine and typically encompasses limited functionality and data processing capabilities.', 'The detection process is based on comprehensive assessments, including the number of service entities, lines of code, number of files, number of APIs, and other factors.', 'The proliferation of nanoservices amplifies the overall system complexity and coupling, compromising maintainability, interaction capability, and modularity.', 'This is primarily caused by an excessive refinement of the domain model or an overemphasis on the decoupling of microservices.', 'These services possess minimal functionality and are specifically designed to address narrow, specific problems. For instance, a file upload service is a dedicated microservice responsible for handling file uploads and storage, tasked with receiving files and storing them in the appropriate location.', '[\"@article{de2021identifying,  title={Identifying architectural technical debt, principal, and interest in microservices: A multiple-case study},  author={de Toledo, Saulo S and Martini, Antonio and Sj{\\\\o}berg, Dag IK},  journal={Journal of Systems and Software},  volume={177},  pages={110968},  year={2021},  publisher={Elsevier}}\",\"@inproceedings{palma2015study,  title={A study on the taxonomy of service antipatterns},  author={Palma, Francis and Mohay, Naouel},  booktitle={2015 IEEE 2nd International Workshop on Patterns Promotion and Anti-patterns Prevention (PPAP)},  pages={5--8},  year={2015},  organization={IEEE}}\",\"  @inproceedings{palma2014specification,   title={Specification and detection of SOA antipatterns in web services},   author={Palma, Francis and Moha, Naouel and Tremblay, Guy and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   booktitle={Software Architecture: 8th European Conference, ECSA 2014, Vienna, Austria, August 25-29, 2014. Proceedings 8},   pages={58--73},   year={2014},   organization={Springer} }\",\"  @inproceedings{palma2014investigating,   title={Investigating the change-proneness of service patterns and antipatterns},   author={Palma, Francis and An, Le and Khomh, Foutse and Moha, Naouel and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   booktitle={2014 IEEE 7th International Conference on Service-Oriented Computing and Applications},   pages={1--8},   year={2014},   organization={IEEE} }\",\"@inproceedings{matar2023approach,   title={An Approach for Evaluating the Potential Impact of Anti-Patterns on Microservices Performance},   author={Matar, Raghad and Jahi{\\\\\'c}, Jasmin},   booktitle={2023 IEEE 20th International Conference on Software Architecture Companion (ICSA-C)},   pages={167--170},   year={2023},   organization={IEEE} }\",\"@inproceedings{wang2017value,   title={On the value of quality of service attributes for detecting bad design practices},   author={Wang, Hanzhang and Kessentini, Marouane and Hassouna, Taghreed and Ouni, Ali},   booktitle={2017 IEEE International Conference on Web Services (ICWS)},   pages={341--348},   year={2017},   organization={IEEE} }\"]', 'Internal Design', 'Granularity Design', 13, 0);
INSERT INTO `antipattern_info` VALUES (88, 'Mega Microservice', '[\"God object web service\", \"Multi service\", \"God component\",\"Concern overload\"]', 'It refers to microservices that are excessively large and complex, indicating that the microservice\'s granularity is too coarse and it assumes an excessive number of responsibilities.', 'The detection method is based on comprehensive metrics assessments, including the number of service entities, lines of code, files, number of API, and other metrics.', 'This leads to an increased risk of a single point of failure and a reduction in Availability and Reliability. It becomes challenging to meet response time and throughput requirements, which affects the time-behaviour. The presence of complex dependencies between components leads to increased coupling. Moreover, the lack of a proper modular design diminishes modularity, modifiability, and analyzability. The internal complexity also hampers maintainability and testability.', 'Incorrect service splitting results in an excessive coarsening of microservice partitioning.', 'Consider an e-commerce system encompassing order management, inventory management, payment management, and user management. In this scenario, a typical Mega service might consolidate all these functions into a single, massive service. However, such a service comprises multiple unrelated functions, thereby increasing its complexity and making the code challenging to comprehend, maintain, and extend.', '[\"@inproceedings{palma2015study,  title={A study on the taxonomy of service antipatterns},  author={Palma, Francis and Mohay, Naouel},  booktitle={2015 IEEE 2nd International Workshop on Patterns Promotion and Anti-patterns Prevention (PPAP)},  pages={5--8},  year={2015},  organization={IEEE}}\",\"@inproceedings{azadi2019architectural,   title={Architectural smells detected by tools: a catalogue proposal},   author={Azadi, Umberto and Fontana, Francesca Arcelli and Taibi, Davide},   booktitle={2019 IEEE/ACM International Conference on Technical Debt (TechDebt)},   pages={88--97},   year={2019},   organization={IEEE} }\",\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"@inproceedings{palma2014specification,   title={Specification and detection of SOA antipatterns in web services},   author={Palma, Francis and Moha, Naouel and Tremblay, Guy and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   booktitle={Software Architecture: 8th European Conference, ECSA 2014, Vienna, Austria, August 25-29, 2014. Proceedings 8},   pages={58--73},   year={2014},   organization={Springer} }\",\"@inproceedings{palma2014investigating,   title={Investigating the change-proneness of service patterns and antipatterns},   author={Palma, Francis and An, Le and Khomh, Foutse and Moha, Naouel and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   booktitle={2014 IEEE 7th International Conference on Service-Oriented Computing and Applications},   pages={1--8},   year={2014},   organization={IEEE} }\",\"  @inproceedings{matar2023approach,   title={An Approach for Evaluating the Potential Impact of Anti-Patterns on Microservices Performance},   author={Matar, Raghad and Jahi{\\\\\'c}, Jasmin},   booktitle={2023 IEEE 20th International Conference on Software Architecture Companion (ICSA-C)},   pages={167--170},   year={2023},   organization={IEEE} }\",\"@article{tummalapalli2022detection,   title={Detection of web service anti-patterns using weighted extreme learning machine},   author={Tummalapalli, Sahithi and Kumar, Lov and Neti, Lalita Bhanu Murthy and Krishna, Aneesh},   journal={Computer Standards \\\\& Interfaces},   volume={82},   pages={103621},   year={2022},   publisher={Elsevier} }\",\"  @article{zhong2022impacts,   title={Impacts, causes, and solutions of architectural smells in microservices: An industrial investigation},   author={Zhong, Chenxing and Huang, Huang and Zhang, He and Li, Shanshan},   journal={Software: Practice and Experience},   volume={52},   number={12},   pages={2574--2597},   year={2022},   publisher={Wiley Online Library} }\",\"  @inproceedings{wang2017value,   title={On the value of quality of service attributes for detecting bad design practices},   author={Wang, Hanzhang and Kessentini, Marouane and Hassouna, Taghreed and Ouni, Ali},   booktitle={2017 IEEE International Conference on Web Services (ICWS)},   pages={341--348},   year={2017},   organization={IEEE} }\",\"@inproceedings{schirgi2021quality,   title={Quality assurance for microservice architectures},   author={Schirgi, Thomas and Brenner, Eugen},   booktitle={2021 IEEE 12th International Conference on Software Engineering and Service Science (ICSESS)},   pages={76--80},   year={2021},   organization={IEEE} }\"]', 'Internal Design', 'Granularity Design', 10, 0);
INSERT INTO `antipattern_info` VALUES (89, 'Insufficient Message Traceability', NULL, 'This term refers to the absence of adequate traceability and observability of messages exchanged between microservices.', 'Analyze logs or implement interceptors to identify specific fields within messages.', 'Insufficient traceability of messages diminishes the system\'s analyzability, complicating monitoring and troubleshooting processes.', 'This is primarily caused by developers not adequately considering the necessity of message tracing or disregarding the significance of logging.', 'For instance, if the order service lacks a sufficient message tracking mechanism, it becomes challenging to trace the order processing workflow, including order creation, payment, and delivery. This may result in troubleshooting difficulties related to order processing issues, such as lost orders or duplicate processing.', '[\"@article{de2021identifying,  title={Identifying architectural technical debt, principal, and interest in microservices: A multiple-case study},  author={de Toledo, Saulo S and Martini, Antonio and Sj{\\\\o}berg, Dag IK},  journal={Journal of Systems and Software},  volume={177},  pages={110968},  year={2021},  publisher={Elsevier}}\"]', 'Communication & Interaction', 'Communication', 1, 0);
INSERT INTO `antipattern_info` VALUES (90, 'Use Of Complex API Calls When Messaging Is a Simpler Solution', NULL, 'It refers to the utilization of synchronous calls when asynchronous calls would be more suitable.', 'Analyze communication patterns and combine with code logic to make a comprehensive decision', 'This leads to increased coupling between services, thereby diminishing the testability of the system.', 'This is primarily caused by misleading technology selection or a lack of design thinking.', 'For instance, if the order service directly updates the data of the inventory service through intricate API calls, it intensifies the coupling between these services, rendering it more challenging for them to independently evolve and expand.', '[\"@article{de2021identifying,  title={Identifying architectural technical debt, principal, and interest in microservices: A multiple-case study},  author={de Toledo, Saulo S and Martini, Antonio and Sj{\\\\o}berg, Dag IK},  journal={Journal of Systems and Software},  volume={177},  pages={110968},  year={2021},  publisher={Elsevier}}\"]', 'Communication & Interaction', 'Communication', 1, 0);
INSERT INTO `antipattern_info` VALUES (91, 'Use Of Business Logic In Communication Among Services', 'Logic implemented in the communication layer', ' It pertains to the utilization of business logic within the communication layer of a service (such as message queues or transit components), resulting in data modifications during transmission.', ' The detection process involves identifying communication layer middleware, such as message queues or transit components, and analyzing whether they incorporate business logic.', 'The dispersion of business logic within the communication layer diminishes the analyzability and reliability of the system. Modifying the business logic necessitates alterations in multiple locations, thereby reducing maintainability. It hampers the ability of services to expand, diminishing adaptability.', 'These issues primarily arise due to misleading technology selection or a lack of design thinking.', 'For instance, when a user places an order, the order service can transmit the order information to a message queue. In this scenario, a portion of the inventory service\'s logic is executed within the message queue, allowing the inventory service to collaborate with the order service in completing the product inventory update.', '[\"@article{de2021identifying,  title={Identifying architectural technical debt, principal, and interest in microservices: A multiple-case study},  author={de Toledo, Saulo S and Martini, Antonio and Sj{\\\\o}berg, Dag IK},  journal={Journal of Systems and Software},  volume={177},  pages={110968},  year={2021},  publisher={Elsevier}}\",\"@inproceedings{de2019architectural,   title={Architectural technical debt in microservices: a case study in a large company},   author={De Toledo, Saulo Soares and Martini, Antonio and Przybyszewska, Agata and Sj{\\\\o}berg, Dag IK},   booktitle={2019 IEEE/ACM International Conference on Technical Debt (TechDebt)},   pages={78--87},   year={2019},   organization={IEEE} }\",\"@inproceedings{de2021reducing,   title={Reducing Incidents in Microservices by Repaying Architectural Technical Debt},   author={de Toledo, Saulo S and Martini, Antonio and Sj{\\\\o}berg, Dag IK and Przybyszewska, Agata and Frandsen, Johannes Skov},   booktitle={2021 47th Euromicro Conference on Software Engineering and Advanced Applications (SEAA)},   pages={196--205},   year={2021},   organization={IEEE} }\"]', 'Communication & Interaction', 'Communication', 10, 0);
INSERT INTO `antipattern_info` VALUES (92, 'Hardcoded Endpoints', 'Endpoint-based service interactions', 'This term refers to the hard-coded endpoints in a service\'s code, typically in the form of IP:PORT, which enable direct communication with other services  or database.', 'Formulate a regular expression that matches IP:PORT, scanning source files for detection', 'The presence of scattered hard-coded endpoint information throughout the code hinders the analysis of service dependencies, thereby reducing analyzability. Furthermore, any changes in the location of the target service (such as IP address or port number) require modifications to all services utilizing the hard-coded endpoint, which diminishes scalability. Additionally, if the service instance expands to multiple instances, the hardcoding restricts communication to just one instance, leading to resource wastage and a decline in resource utilization.', 'lack of consideration for scalability and adaptability, as well as  lack of awareness regarding the associated problems and challenges.', 'The Order Service directly sends HTTP requests (e.g., http://172.16.17.55:8080/v1/products) to the Merchandise Service using a hard-coded endpoint in order to retrieve product information.', '[\"@article{taibi2018definition,   title={On the definition of microservice bad smells},   author={Taibi, Davide and Lenarduzzi, Valentina},   journal={IEEE software},   volume={35},   number={3},   pages={56--62},   year={2018},   publisher={IEEE} }\",\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"@inproceedings{pigazzini2020towards,   title={Towards microservice smells detection},   author={Pigazzini, Ilaria and Fontana, Francesca Arcelli and Lenarduzzi, Valentina and Taibi, Davide},   booktitle={Proceedings of the 3rd International Conference on Technical Debt},   pages={92--97},   year={2020} }\",\"@inproceedings{pulnil2022microservices,   title={A microservices quality model based on microservices anti-patterns},   author={Pulnil, Sermsook and Senivongse, Twittie},   booktitle={2022 19th International Joint Conference on Computer Science and Software Engineering (JCSSE)},   pages={1--6},   year={2022},   organization={IEEE} }\",\"@article{walker2020automated,   title={Automated code-smell detection in microservices through static analysis: A case study},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   journal={Applied Sciences},   volume={10},   number={21},   pages={7800},   year={2020},   publisher={MDPI} }\",\"@inproceedings{walker2021automated,   title={Automated microservice code-smell detection},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   booktitle={Information Science and Applications: Proceedings of ICISA 2020},   pages={211--221},   year={2021},   organization={Springer} }\",\"@inproceedings{brogi2020freshening,   title={Freshening the air in microservices: Resolving architectural smells via refactoring},   author={Brogi, Antonio and Neri, Davide and Soldani, Jacopo},   booktitle={Service-Oriented Computing--ICSOC 2019 Workshops: WESOACS, ASOCA, ISYCC, TBCE, and STRAPS, Toulouse, France, October 28--31, 2019, Revised Selected Papers 17},   pages={17--29},   year={2020},   organization={Springer} }\",\"@inproceedings{soldani2023kubernetes,   title={Kubernetes-Enabled Detection and Resolution of Architectural Smells for Microservices},   author={Soldani, Jacopo and Rendina, Davide and Fontana, Francesca Arcelli and Brogi, Antonio},   booktitle={2023 IEEE International Conference on Service-Oriented System Engineering (SOSE)},   pages={75--80},   year={2023},   organization={IEEE} }\",\"@inproceedings{schirgi2021quality,   title={Quality assurance for microservice architectures},   author={Schirgi, Thomas and Brenner, Eugen},   booktitle={2021 IEEE 12th International Conference on Software Engineering and Service Science (ICSESS)},   pages={76--80},   year={2021},   organization={IEEE} }\"]', 'Communication & Interaction', 'Communication', 3, 0);
INSERT INTO `antipattern_info` VALUES (93, 'Lack Of Communication Standards Among Microservices', 'There is no approach to standardise the communication model among services', 'In a microservice system, there exist multiple communication standards, with each service development team having its own set of standards. This diversity of communication standards complicates the interaction between different services.', '1. Detect whether data format mixing is taken in different microservices, i.e., detect each service dependency (JSON, XML, etc.). 2. Iterate through the dependencies of each service and determine whether a threshold number of communication protocols (including message queuing protocols such as AMQP) is exceeded.', 'As a result, the entire system is burdened with the need to maintain multiple communication standards, which diminishes its reliability and adaptability.', 'Lack of unified guidance and specification, leading to independent decision-making by the teams.', 'Let\'s consider an e-commerce platform comprising two microservices: a product service and a review service. The product service handles the management of product information, whereas the review service is responsible for managing user reviews. Unfortunately, due to the absence of communication standards, the product service and the review service adopt different data formats to represent product information and reviews. Specifically, the product service utilizes JSON format for product information, while the review service relies on XML format for reviews. Consequently, when the review service needs to obtain product information, it must convert the JSON-formatted data returned by the product service into XML format, resulting in increased complexity and system overhead.', '[\"@inproceedings{de2019architectural,   title={Architectural technical debt in microservices: a case study in a large company},   author={De Toledo, Saulo Soares and Martini, Antonio and Przybyszewska, Agata and Sj{\\\\o}berg, Dag IK},   booktitle={2019 IEEE/ACM International Conference on Technical Debt (TechDebt)},   pages={78--87},   year={2019},   organization={IEEE} }\",\"@inproceedings{de2021reducing,   title={Reducing Incidents in Microservices by Repaying Architectural Technical Debt},   author={de Toledo, Saulo S and Martini, Antonio and Sj{\\\\o}berg, Dag IK and Przybyszewska, Agata and Frandsen, Johannes Skov},   booktitle={2021 47th Euromicro Conference on Software Engineering and Advanced Applications (SEAA)},   pages={196--205},   year={2021},   organization={IEEE} }\"]', 'Communication & Interaction', 'Communication', 5, 0);
INSERT INTO `antipattern_info` VALUES (94, 'Empty Messages', NULL, 'Empty messages, characterized by the absence of actual valid data, are commonly encountered during communication between microservices for signaling and triggering behavior.', 'By detecting whether the URI of a get request contains parameter fields and whether the request body of other request methods is empty.', 'The presence of empty messages introduces additional processing logic, thereby increasing system complexity and diminishing maintainability. In testing scenarios, special processing logic may be necessary to simulate or handle empty messages, thereby reducing testability. Since null messages lack actual valid data, they may fail to provide sufficient information for ensuring accurate reception and comprehension. This can result in signal loss, false behavioral triggers, or inconsistent state, thereby compromising the reliability of the system. Empty messages, lacking actual valid data, are insufficient for ensuring data integrity.', ' Lack of clear and unambiguous communication protocols is the underlying cause for this issue.', 'Let\'s consider an e-commerce platform consisting of an order service and an inventory service. The order service is responsible for managing product information. Whenever a new order is generated, the order service must inform the inventory service to update the inventory information accordingly. To accomplish this, the order service sends an empty message to the inventory service as a signal for inventory update. Upon receiving the null message, the inventory service activates the corresponding inventory update logic, which may involve retrieving updated details from other services, to update the inventory information in response to the signal.', '[\"@article{coscia2014refactoring,   title={Refactoring code-first Web Services for early avoiding WSDL anti-patterns: Approach and comprehensive assessment},   author={Coscia, Jos{\\\\\'e} Luis Ordiales and Mateos, Cristian and Crasso, Marco and Zunino, Alejandro},   journal={Science of Computer Programming},   volume={89},   pages={374--407},   year={2014},   publisher={Elsevier} }\"]', 'Communication & Interaction', 'Communication', 10, 0);
INSERT INTO `antipattern_info` VALUES (95, 'Timeout', NULL, 'This situation refers to when a service experiences excessively long response times or becomes unavailable, causing the caller to wait for an extended period and leading to resource wastage.', 'It can be detected by comparing the service response time with a predefined threshold value.', 'When the service response time exceeds acceptable limits, it leads to increased time-behavior and reduced availability. This can have a ripple effect on other microservices or client applications that rely on the service, ultimately impacting the overall performance  efficiency of the system.', ' Insufficient strategies to address service unavailability or prolonged response times can be attributed to this issue. By implementing circuit breakers and configuring their parameters appropriately (such as timeout time and error threshold), the system can better manage service unavailability and response delays, leading to improved stability and performance.', 'Let\'s consider an order service and an inventory service scenario. The order service verifies the availability of goods by invoking the inventory service and finalizes the order accordingly. When the order service calls the inventory service, it sets a timeout of 3 seconds and configures a maximum of 2 retries. In the event that no response is received from the inventory service within 3 seconds, the order service promptly resends the request, allowing a maximum of 2 retries. If no response is received even after 2 retries, the order service triggers a circuit breaker open action. This mechanism ensures fast failure and provides alternate options such as utilizing cached data or reverting to default values.', '[\"@inproceedings{schirgi2021quality,   title={Quality assurance for microservice architectures},   author={Schirgi, Thomas and Brenner, Eugen},   booktitle={2021 IEEE 12th International Conference on Software Engineering and Service Science (ICSESS)},   pages={76--80},   year={2021},   organization={IEEE} }\"]', 'Communication & Interaction', 'Communication', 4, 0);
INSERT INTO `antipattern_info` VALUES (96, 'Wobbly Service Interactions', NULL, 'This term describes the instability in the interaction between a microservice and other services. Specifically, it occurs when service A depends on one or more functions provided by service B without having a mechanism to handle service B\'s failures. ', 'Analyze dependencies between services and judge whether to adopt a failure handling mechanism.', 'When a service fails, it rapidly propagates to other services, diminishing the overall reliability of the system.', 'The lack of adequate fault handling and fault tolerance mechanisms.', 'Let\'s consider an e-commerce platform comprising multiple microservices, such as product services, inventory services, and order services. These microservices exhibit direct dependencies, with the order service relying on both the product service and the inventory service. In the event of a failure in the product service, the failure can rapidly propagate to the order service, impeding the retrieval of accurate product information and leading to order processing failures. Consequently, this fault propagation significantly diminishes the overall availability of the system.', '[\"@inproceedings{brogi2020freshening,   title={Freshening the air in microservices: Resolving architectural smells via refactoring},   author={Brogi, Antonio and Neri, Davide and Soldani, Jacopo},   booktitle={Service-Oriented Computing--ICSOC 2019 Workshops: WESOACS, ASOCA, ISYCC, TBCE, and STRAPS, Toulouse, France, October 28--31, 2019, Revised Selected Papers 17},   pages={17--29},   year={2020},   organization={Springer} }\",\"@inproceedings{soldani2023kubernetes,   title={Kubernetes-Enabled Detection and Resolution of Architectural Smells for Microservices},   author={Soldani, Jacopo and Rendina, Davide and Fontana, Francesca Arcelli and Brogi, Antonio},   booktitle={2023 IEEE International Conference on Service-Oriented System Engineering (SOSE)},   pages={75--80},   year={2023},   organization={IEEE} }\"]', 'Communication & Interaction', 'Interaction', 4, 0);
INSERT INTO `antipattern_info` VALUES (97, 'Service Chain', NULL, 'This term describes the process of continuously requesting multiple services in order to fulfill a specific business objective during request processing. Each service is responsible for handling a portion of the logic or providing specific functionalities.', 'To identify this pattern, AOP (aspect-oriented programming) or interceptors can be employed to monitor method calls during runtime and verify if the target of the call is designated as a transaction.', 'The interaction with multiple services amplifies the complexity of the logic and diminishes maintainability. If any of the services exhibit subpar performance or prolonged response times, it can cause delays in the overall service chain, impacting user experience and system performance efficiency. Moreover, excessive dependence on other services intensifies coupling, making fault propagation more likely and escalating debugging expenses, thereby compromising system reliability.', 'Inappropriate service splitting results in tightly coupled services.', 'For example, in a movie ticket booking service, the process begins with a call to the movie resource service to retrieve all currently available movie resources. Once the desired movie is selected, the ticket booking service proceeds to invoke the payment service for payment processing. Finally, the ticket booking service contacts the order service to generate and handle order information.', '[\"@inproceedings{palma2014investigating,   title={Investigating the change-proneness of service patterns and antipatterns},   author={Palma, Francis and An, Le and Khomh, Foutse and Moha, Naouel and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   booktitle={2014 IEEE 7th International Conference on Service-Oriented Computing and Applications},   pages={1--8},   year={2014},   organization={IEEE} }\"]', 'Communication & Interaction', 'Interaction', 12, 0);
INSERT INTO `antipattern_info` VALUES (98, 'Chatty Service', 'Too many point-to-point connections among services', 'It denotes a service that engages in excessive communication with other services. It occurs when a service needs to make multiple fine-grained operations or retrieve data from multiple sources in order to obtain the required information.', 'Statically analyze the source code to determine the number of calls each service makes to other services, and make a judgment based on whether it exceeds the threshold.', 'Excessive microservice communication leads to heightened network latency and increased volume of data transmission, thereby diminishing the overall performance efficiency of the system. Complete request processing leads to increased time-behavior. Moreover, there is a strong reliance on the implementation details of frequently called services, which in turn reduces maintainability.', 'This issue arises due to unreasonable business logic and API design.', 'When the order service receives an order, it iterates through each item in the order and contacts the inventory service to retrieve the inventory status for each item. This results in frequent communication between services during request processing.', '[\"@inproceedings{palma2015study,  title={A study on the taxonomy of service antipatterns},  author={Palma, Francis and Mohay, Naouel},  booktitle={2015 IEEE 2nd International Workshop on Patterns Promotion and Anti-patterns Prevention (PPAP)},  pages={5--8},  year={2015},  organization={IEEE}}\",\"@inproceedings{de2019architectural,   title={Architectural technical debt in microservices: a case study in a large company},   author={De Toledo, Saulo Soares and Martini, Antonio and Przybyszewska, Agata and Sj{\\\\o}berg, Dag IK},   booktitle={2019 IEEE/ACM International Conference on Technical Debt (TechDebt)},   pages={78--87},   year={2019},   organization={IEEE} }\",\"@inproceedings{palma2014specification,   title={Specification and detection of SOA antipatterns in web services},   author={Palma, Francis and Moha, Naouel and Tremblay, Guy and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   booktitle={Software Architecture: 8th European Conference, ECSA 2014, Vienna, Austria, August 25-29, 2014. Proceedings 8},   pages={58--73},   year={2014},   organization={Springer} }\",\"@article{palma2018unidosa,   title={UniDoSA: the unified specification and detection of service antipatterns},   author={Palma, Francis and Moha, Naouel and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   journal={IEEE Transactions on Software Engineering},   volume={45},   number={10},   pages={1024--1053},   year={2018},   publisher={IEEE} }\",\"  @article{tummalapalli2022detection,   title={Detection of web service anti-patterns using weighted extreme learning machine},   author={Tummalapalli, Sahithi and Kumar, Lov and Neti, Lalita Bhanu Murthy and Krishna, Aneesh},   journal={Computer Standards \\\\& Interfaces},   volume={82},   pages={103621},   year={2022},   publisher={Elsevier} }\"]', 'Communication & Interaction', 'Interaction', 8, 0);
INSERT INTO `antipattern_info` VALUES (99, 'Unnecessary Settings', NULL, 'This refers to the presence of numerous unnecessary settings in the configuration files of microservices. For instance, default parameter values are overridden during actual usage. The configuration parameters of microservices are interdependent and have complex dependencies, resulting in higher maintenance costs for configurations.', 'Perform static analysis on the source code to determine metrics such as the definition, usage, and quantity of configuration parameters in each service, and subsequently make additional determinations.', 'The presence of excessive and unnecessary configuration settings complicates configuration management and decreases the system\'s maintainability. Testers are required to invest additional time and effort in verifying parameter interaction and conflicts due to the complexity of configuration parameters, which decreases testability.', 'The lack of a clear configuration management strategy.', 'When a service is used for data processing and needs to support various data sources, configuration parameters specific to each data source are introduced in the configuration file, leading to configuration overload. To prevent excessive configuration parameters and redundant settings, configurations should be appropriately designed and managed using abstraction and generalization techniques to handle different data source types.', '[\"@article{de2021identifying, title={Identifying architectural technical debt, principal, and interest in microservices: A multiple-case study}, author={de Toledo, Saulo S and Martini, Antonio and Sj{\\\\o}berg, Dag IK}, journal={Journal of Systems and Software}, volume={177}, pages={110968}, year={2021}, publisher={Elsevier} }\", \"@article{de2022accumulation,  title={Accumulation and prioritization of architectural debt in three companies migrating to microservices},  author={De Toledo, Saulo Soares and Martini, Antonio and Nguyen, Phu H and Sj{\\\\o}berg, Dag IK},  journal={IEEE Access},  volume={10},  pages={37422--37445},  year={2022},  publisher={IEEE}}\"]', 'Structure & Infrastructure', 'Infrastructure', 5, 0);
INSERT INTO `antipattern_info` VALUES (100, 'ESB Usage', NULL, 'The primary purpose of an Enterprise Service Bus (ESB) is to facilitate connectivity between heterogeneous systems, resulting in a centralized and heavyweight architecture. However, when ESB-style components are incorporated into a microservices architecture, it introduces complexities in inter-service communication, requiring messages between services to be routed through the ESB.', 'The detection process involves conducting static analysis on the source code to identify the dependencies of each service, including both the services it relies on and the services that depend on it. Based on this analysis, specific thresholds can be established for further determination.', 'By mandating that all communications pass through the ESB, the system topology becomes intricate, resulting in increased complexity and inter-module coupling. This, in turn, adversely affects the system\'s analyzability and fault tolerance. Misusing the ESB undermines the modularity of services, preventing them from communicating and evolving independently. Consequently, services may struggle to handle high concurrency, limiting the scalability of the entire system.', 'The lack of understanding regarding the principles and best practices of microservices architecture.', 'Consider a microservice system consisting of user service, order service, payment service, product service, and inventory service. In this scenario, communication among these services is forced to go through the ESB, resulting in an excessively centralized system topology.', '[\"@article{taibi2018definition,   title={On the definition of microservice bad smells},   author={Taibi, Davide and Lenarduzzi, Valentina},   journal={IEEE software},   volume={35},   number={3},   pages={56--62},   year={2018},   publisher={IEEE} }\",\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"@inproceedings{pulnil2022microservices,   title={A microservices quality model based on microservices anti-patterns},   author={Pulnil, Sermsook and Senivongse, Twittie},   booktitle={2022 19th International Joint Conference on Computer Science and Software Engineering (JCSSE)},   pages={1--6},   year={2022},   organization={IEEE} }\",\"@article{walker2020automated,   title={Automated code-smell detection in microservices through static analysis: A case study},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   journal={Applied Sciences},   volume={10},   number={21},   pages={7800},   year={2020},   publisher={MDPI} }\",\"@inproceedings{walker2021automated,   title={Automated microservice code-smell detection},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   booktitle={Information Science and Applications: Proceedings of ICISA 2020},   pages={211--221},   year={2021},   organization={Springer} }\"]', 'Structure & Infrastructure', 'Infrastructure', 4, 0);
INSERT INTO `antipattern_info` VALUES (101, 'No API-Gateway', 'Not Having an API Gateway', 'The lack of an API Gateway in a microservices architecture is a notable drawback. An API Gateway serves as a centralized service positioned at the front end of a microservices architecture, handling all external requests and responses. It provides consistent interfaces and performs protocol conversions, shielding external clients from the intricacies of the underlying microservices. As the number of services grows, the limitations stemming from the lack of an API Gateway become more apparent, resulting in decreased maintainability.', 'The analysis involves examining the microservice dependency files and configuration file source code to determine if gateway-related dependencies have been introduced and if routing rules have been configured in the configuration file.', 'In the absence of an API Gateway, clients communicate directly with the services, potentially necessitating independent implementation of service discovery and load balancing. This increases system complexity and compromises security, maintainability, and analyzability. Moreover, when new microservices need to be added, modifying the source code of multiple clients becomes necessary, thereby reducing modifiability.', 'The lack of timely architectural adjustments and improvements as the system evolves leads to the lack of an API Gateway.', 'A system with only two microservices allows clients to communicate with them directly. As the system grows and the number of microservices increases to dozens, the client needs to manage a large number of service invocation logics and routing rules, leading to increased complexity.', '[\"@article{taibi2018definition,   title={On the definition of microservice bad smells},   author={Taibi, Davide and Lenarduzzi, Valentina},   journal={IEEE software},   volume={35},   number={3},   pages={56--62},   year={2018},   publisher={IEEE} }\",\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"@inproceedings{pulnil2022microservices,   title={A microservices quality model based on microservices anti-patterns},   author={Pulnil, Sermsook and Senivongse, Twittie},   booktitle={2022 19th International Joint Conference on Computer Science and Software Engineering (JCSSE)},   pages={1--6},   year={2022},   organization={IEEE} }\",\"@article{walker2020automated,   title={Automated code-smell detection in microservices through static analysis: A case study},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   journal={Applied Sciences},   volume={10},   number={21},   pages={7800},   year={2020},   publisher={MDPI} }\",\"@inproceedings{walker2021automated,   title={Automated microservice code-smell detection},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   booktitle={Information Science and Applications: Proceedings of ICISA 2020},   pages={211--221},   year={2021},   organization={Springer} }\",\"  @inproceedings{brogi2020freshening,   title={Freshening the air in microservices: Resolving architectural smells via refactoring},   author={Brogi, Antonio and Neri, Davide and Soldani, Jacopo},   booktitle={Service-Oriented Computing--ICSOC 2019 Workshops: WESOACS, ASOCA, ISYCC, TBCE, and STRAPS, Toulouse, France, October 28--31, 2019, Revised Selected Papers 17},   pages={17--29},   year={2020},   organization={Springer} }\",\"@inproceedings{soldani2023kubernetes,   title={Kubernetes-Enabled Detection and Resolution of Architectural Smells for Microservices},   author={Soldani, Jacopo and Rendina, Davide and Fontana, Francesca Arcelli and Brogi, Antonio},   booktitle={2023 IEEE International Conference on Service-Oriented System Engineering (SOSE)},   pages={75--80},   year={2023},   organization={IEEE} }\",\"@inproceedings{bacchiega2022microservices,   title={Microservices smell detection through dynamic analysis},   author={Bacchiega, Paolo and Pigazzini, Ilaria and Fontana, Francesca Arcelli},   booktitle={2022 48th Euromicro Conference on Software Engineering and Advanced Applications (SEAA)},   pages={290--293},   year={2022},   organization={IEEE} }\"]', 'Structure & Infrastructure', 'Infrastructure', 11, 0);
INSERT INTO `antipattern_info` VALUES (102, 'No Service Discovery', 'No service registry', 'In microservice architectures, the Service Discovery pattern is commonly employed to address communication and orchestration challenges among services. However, in the absence of proper service discovery mechanisms, as observed in the no service discovery smell, manual modification of endpoint information becomes necessary when the location of a service changes.', 'The analysis entails examining the microservice dependency files and configuration file source code to verify the introduction of service discovery-related dependencies and configuration information.', 'Communication between services becomes hardcoded, requiring manual code modification when the location of a service changes. This hampers adaptability, scalability, and installability, while also diminishing the system\'s maintainability. In the event of a service instance failure or unavailability, other microservices cannot automatically switch to alternative instances, thereby impeding failure recovery and reducing recoverability and availability. The absence of a service discovery mechanism complicates the collection and monitoring of service metrics, consequently diminishing analyzability.', 'The  lack of comprehensive recognition of the significance of service discovery.', 'The code for an order service may include the IP address and port number of a user service. Consequently, if the location or configuration of the user service changes, manual modification of the order service code and subsequent service redeployment become necessary.', '[\"@article{balalaie2018microservices,   title={Microservices migration patterns},   author={Balalaie, Armin and Heydarnoori, Abbas and Jamshidi, Pooyan and Tamburri, Damian A and Lynn, Theo},   journal={Software: Practice and Experience},   volume={48},   number={11},   pages={2019--2042},   year={2018},   publisher={Wiley Online Library} }\",\"  @inproceedings{messina2016database,   title={The database-is-the-service pattern for microservice architectures},   author={Messina, Antonio and Rizzo, Riccardo and Storniolo, Pietro and Tripiciano, Mario and Urso, Alfonso},   booktitle={Information Technology in Bio-and Medical Informatics: 7th International Conference, ITBAM 2016, Porto, Portugal, September 5-8, 2016, Proceedings 7},   pages={223--233},   year={2016},   organization={Springer} }\",\"  @inproceedings{brown2016implementation,   title={Implementation patterns for microservices architectures},   author={Brown, Kyle and Woolf, Bobby},   booktitle={Proceedings of the 23rd conference on pattern languages of programs},   pages={1--35},   year={2016} }\"]', 'Structure & Infrastructure', 'Infrastructure', 10, 0);
INSERT INTO `antipattern_info` VALUES (103, 'Bottleneck Service', NULL, 'It refers to a critical service that is highly relied upon by other services or highly used by clients, often characterized by high incoming and low outgoing traffic.', 'The identification process involves analyzing the service dependencies and calculating the frequency of service invocations within a specific time period.', 'The increased workload on the service leads to prolonged response times, thereby impacting time-behavior and reducing availability.', 'Insufficient consideration of decoupling and independence between services. The functions and responsibilities of a service may be excessively centralized, resulting in excessive reliance on that service by other services or clients.', 'The order service plays a crucial role in managing various order-related operations, such as order creation, status updates, and retrieval of order information. However, due to its widespread utilization throughout the system, it becomes a Bottleneck Service. The high volume of order requests places a significant burden on this service, causing prolonged response times. Consequently, other services or clients may experience considerable delays when processing orders.', '[\"@inproceedings{palma2015study,  title={A study on the taxonomy of service antipatterns},  author={Palma, Francis and Mohay, Naouel},  booktitle={2015 IEEE 2nd International Workshop on Patterns Promotion and Anti-patterns Prevention (PPAP)},  pages={5--8},  year={2015},  organization={IEEE}}\",\"@inproceedings{palma2014investigating,   title={Investigating the change-proneness of service patterns and antipatterns},   author={Palma, Francis and An, Le and Khomh, Foutse and Moha, Naouel and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   booktitle={2014 IEEE 7th International Conference on Service-Oriented Computing and Applications},   pages={1--8},   year={2014},   organization={IEEE} }\",\"  @inproceedings{matar2023approach,   title={An Approach for Evaluating the Potential Impact of Anti-Patterns on Microservices Performance},   author={Matar, Raghad and Jahi{\\\\\'c}, Jasmin},   booktitle={2023 IEEE 20th International Conference on Software Architecture Companion (ICSA-C)},   pages={167--170},   year={2023},   organization={IEEE} }\"]', 'Structure & Infrastructure', 'Structure', 2, 0);
INSERT INTO `antipattern_info` VALUES (104, 'Chaotic Independence', NULL, 'It refers to the presence of one or more excessively lengthy sequences of service calls within a microservice system.', 'Detection involves collecting logs generated during service calls, tracing the service call process, and determining the length of the service call chain.', 'When a service within a call chain fails, the failure quickly propagates to other services, resulting in cascading failures that decrease the overall system availability. A long service call chain increases the complexity of business logic and introduces additional network communication overhead, leading to reduced performance efficiency and testability of the system.', 'The services are not properly divided, and the dependency relationships between services are not adequately designed.', 'The user service receives user order requests, verifies the user\'s identity, and then calls the order service to create the order. The order service subsequently calls the payment service to process the order expenditure, and the payment service in turn calls the inventory service to check the goods inventory. The user service, order service, payment service, and inventory service form a lengthy call chain.', '[\"@article{zhou2023revisiting,   title={Revisiting the practices and pains of microservice architecture in reality: An industrial inquiry},   author={Zhou, Xin and Li, Shanshan and Cao, Lingli and Zhang, He and Jia, Zijia and Zhong, Chenxing and Shan, Zhihao and Babar, Muhammad Ali},   journal={Journal of Systems and Software},   volume={195},   pages={111521},   year={2023},   publisher={Elsevier} }\"]', 'Structure & Infrastructure', 'Structure', 5, 0);
INSERT INTO `antipattern_info` VALUES (105, 'Cyclic Dependency', 'Cross-module cycle', 'It refers to the case where a ring call occurs in a complete request call chain in a microservice system.', 'Static Detection: Construct a dependency graph between services by analyzing the source code statically. Then, determine the presence of an invocation loop through methods such as topological sorting. Dynamic Detection: Set up a request interceptor to update the current service ID and predecessor service ID in the request header. When the API receives the request, relevant link information is written into the log. Log information collected in real-time within a recent time window allows the restoration of the actual service call chain using the link information. Determination can be made using topological sorting or SCC algorithm.', 'It increases coupling between services, reducing modularity, reliability, and maintainability. t creates a vulnerability to cascading failures, reducing fault tolerance. It makes it difficult to extract specific services for independent reuse, diminishing reusability. The complexity of invocation relationships decreases analyzability, hampers coping with high loads, reducing scalability and adaptability. Changes to one service affect other services within the circular call chain, reducing modifiability. The execution of tests becomes challenging, as it is difficult to simulate and isolate specific services, decreasing testability.', 'The presence of confusing dependencies, complex business logic, and a lack of appropriate interface design contribute to cyclic  dependency.', 'The user service requires personalized product recommendations for users. As a result, it calls the recommendation service to obtain the recommendation results. The recommendation service, in turn, calls the user service to retrieve more detailed user information for accurate recommendations. This creates a cyclic call chain between the user service and the recommendation service.', '[\"@article{taibi2018definition,   title={On the definition of microservice bad smells},   author={Taibi, Davide and Lenarduzzi, Valentina},   journal={IEEE software},   volume={35},   number={3},   pages={56--62},   year={2018},   publisher={IEEE} }\",\"@inproceedings{azadi2019architectural,   title={Architectural smells detected by tools: a catalogue proposal},   author={Azadi, Umberto and Fontana, Francesca Arcelli and Taibi, Davide},   booktitle={2019 IEEE/ACM International Conference on Technical Debt (TechDebt)},   pages={88--97},   year={2019},   organization={IEEE} }\",\"@inproceedings{roveda2018towards,   title={Towards an architectural debt index},   author={Roveda, Riccardo and Fontana, Francesca Arcelli and Pigazzini, Ilaria and Zanoni, Marco},   booktitle={2018 44th Euromicro Conference on Software Engineering and Advanced Applications (SEAA)},   pages={408--416},   year={2018},   organization={IEEE} }\",\"@inproceedings{mo2015hotspot,   title={Hotspot patterns: The formal definition and automatic detection of architecture smells},   author={Mo, Ran and Cai, Yuanfang and Kazman, Rick and Xiao, Lu},   booktitle={2015 12th Working IEEE/IFIP Conference on Software Architecture},   pages={51--60},   year={2015},   organization={IEEE} }\",\"  @article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"@article{fontana2019architectural,   title={Are architectural smells independent from code smells? An empirical study},   author={Fontana, Francesca Arcelli and Lenarduzzi, Valentina and Roveda, Riccardo and Taibi, Davide},   journal={Journal of Systems and Software},   volume={154},   pages={139--156},   year={2019},   publisher={Elsevier} }\",\"  @inproceedings{pigazzini2020towards,   title={Towards microservice smells detection},   author={Pigazzini, Ilaria and Fontana, Francesca Arcelli and Lenarduzzi, Valentina and Taibi, Davide},   booktitle={Proceedings of the 3rd International Conference on Technical Debt},   pages={92--97},   year={2020} }\",\"  @inproceedings{pulnil2022microservices,   title={A microservices quality model based on microservices anti-patterns},   author={Pulnil, Sermsook and Senivongse, Twittie},   booktitle={2022 19th International Joint Conference on Computer Science and Software Engineering (JCSSE)},   pages={1--6},   year={2022},   organization={IEEE} }\",\"  @article{walker2020automated,   title={Automated code-smell detection in microservices through static analysis: A case study},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   journal={Applied Sciences},   volume={10},   number={21},   pages={7800},   year={2020},   publisher={MDPI} }\",\"@inproceedings{walker2021automated,   title={Automated microservice code-smell detection},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   booktitle={Information Science and Applications: Proceedings of ICISA 2020},   pages={211--221},   year={2021},   organization={Springer} }\",\"@article{zhong2022impacts,   title={Impacts, causes, and solutions of architectural smells in microservices: An industrial investigation},   author={Zhong, Chenxing and Huang, Huang and Zhang, He and Li, Shanshan},   journal={Software: Practice and Experience},   volume={52},   number={12},   pages={2574--2597},   year={2022},   publisher={Wiley Online Library} }\",\"@inproceedings{bacchiega2022microservices,   title={Microservices smell detection through dynamic analysis},   author={Bacchiega, Paolo and Pigazzini, Ilaria and Fontana, Francesca Arcelli},   booktitle={2022 48th Euromicro Conference on Software Engineering and Advanced Applications (SEAA)},   pages={290--293},   year={2022},   organization={IEEE} }\",\"@inproceedings{pigazzini2019tool,   title={Tool support for the migration to microservice architecture: An industrial case study},   author={Pigazzini, Ilaria and Arcelli Fontana, Francesca and Maggioni, Andrea},   booktitle={Software Architecture: 13th European Conference, ECSA 2019, Paris, France, September 9--13, 2019, Proceedings 13},   pages={247--263},   year={2019},   organization={Springer} }\",\"@inproceedings{schirgi2021quality,   title={Quality assurance for microservice architectures},   author={Schirgi, Thomas and Brenner, Eugen},   booktitle={2021 IEEE 12th International Conference on Software Engineering and Service Science (ICSESS)},   pages={76--80},   year={2021},   organization={IEEE} }\"]', 'Structure & Infrastructure', 'Structure', 10, 0);
INSERT INTO `antipattern_info` VALUES (106, 'Sand Pile ', NULL, 'It refers to the situation where multiple nano services in a system share public data, resulting in tight coupling between them.', 'Comprehensive judgment based on service business logic, dependencies and granularity.', 'The tight coupling among multiple nano services reduces the modularity of the overall service architecture.', 'Improper cutting of services and excessive sharing of data.', 'Consider an e-commerce platform consisting of three nano-services: product service, shopping cart service, and order service. Both the shopping cart service and order service require access to the public data of the product service, specifically, product information. Due to excessive data sharing, a tight coupling develops between the shopping cart service, order service, and product service. Consequently, when the data structure of the product service changes, the code of the shopping cart service and order service may need to be modified to accommodate the new data structure.', '[\"@inproceedings{palma2015study, title={A study on the taxonomy of service antipatterns}, author={Palma, Francis and Mohay, Naouel}, booktitle={2015 IEEE 2nd International Workshop on Patterns Promotion and Anti-patterns Prevention (PPAP)}, pages={5--8}, year={2015}, organization={IEEE}}\", \"@article{palma2018unidosa,   title={UniDoSA: the unified specification and detection of service antipatterns},   author={Palma, Francis and Moha, Naouel and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   journal={IEEE Transactions on Software Engineering},   volume={45},   number={10},   pages={1024--1053},   year={2018},   publisher={IEEE} }\"]', 'Structure & Infrastructure', 'Structure', 1, 0);
INSERT INTO `antipattern_info` VALUES (107, 'Knot Service', NULL, 'It refer to a collection of services with very low cohesion but high coupling. In this scenario, multiple services communicate with the same service, resembling a node entangled with an excessive number of threads, resulting in a perplexing system architecture.', 'Detection involves assessing the dependency relationships between services and making comprehensive determinations based on their functional responsibilities.', 'As a result, the execution path becomes convoluted, leading to longer response times and adversely affecting the system\'s time behavior.', 'Poor dependency design.', 'Suppose there exists an online social media platform comprising various microservices, including user management, post publishing, commenting, and liking. Initially, these microservices were designed to communicate with each other through a loosely defined API. However, developers eventually recognized the significance of a central service known as the Notification Service, which proved critical to multiple microservices. Initially, the Notification Service was responsible for managing message notifications and event reminders between users. Nevertheless, as the platform expanded and its functionality grew, other microservices began to rely on this particular service. For instance:\r\n\r\n1. The user management service necessitates the Notification Service to send welcome emails to newly registered users.\r\n2. The post publishing service relies on the Notification Service to send alerts to the followers of a user.\r\n3. The commenting service relies on the Notification Service to inform the author of a post about new comments.\r\n4. The liking service requires the Notification Service to notify the author of a post about new likes.\r\n\r\nAs these dependencies increase, the microservice becomes tightly coupled with the notification service. Consequently, any changes or issues that arise within the notification service will inevitably impact the other microservices.', '[\"@inproceedings{palma2015study, title={A study on the taxonomy of service antipatterns}, author={Palma, Francis and Mohay, Naouel}, booktitle={2015 IEEE 2nd International Workshop on Patterns Promotion and Anti-patterns Prevention (PPAP)}, pages={5--8}, year={2015}, organization={IEEE}}\", \"@inproceedings{palma2014investigating,   title={Investigating the change-proneness of service patterns and antipatterns},   author={Palma, Francis and An, Le and Khomh, Foutse and Moha, Naouel and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   booktitle={2014 IEEE 7th International Conference on Service-Oriented Computing and Applications},   pages={1--8},   year={2014},   organization={IEEE} }\"]', 'Structure & Infrastructure', 'Structure', 1, 0);
INSERT INTO `antipattern_info` VALUES (108, 'Hub-like Dependency', NULL, ' It refers to a service that maintains extensive incoming and outgoing relationships with numerous other services. Typically, this service plays a central role, and any modifications made to it can have a significant impact on multiple services.', 'The identification process is based on analyzing the incoming and outgoing relationships between services.', 'When a service has numerous incoming and outgoing relationships, it leads to increased coupling between modules and a reduction in modularity, modifiability, and analyzability.', 'Poor dependency design.', 'Let us consider a hypothetical social media platform comprising several microservices, namely the user service, user relationship management service, post service, follow service, and recommendation service. In this scenario, the post service may require access to the user relationship management service to obtain a list of followers for users. This information is crucial in determining which users should receive notifications or updates pertaining to posts. Similarly, the follow service may need to establish communication with the user relationship management service to retrieve the follow status or number of followers for other users. This data is essential for displaying pertinent information in the user interface. Additionally, the recommendation service might rely on the user relationship management service to acquire a user\'s list of followed accounts or friends. This is necessary to generate personalized recommendation content tailored to the user\'s preferences. Consequently, the user relationship management service must communicate with other services to keep the follow status, friend list, and notification-related information of users updated. For example, when a user decides to unfollow another user, the user relationship management service should promptly notify the post service to cease sending relevant notifications to the user.', '[\"@inproceedings{azadi2019architectural,   title={Architectural smells detected by tools: a catalogue proposal},   author={Azadi, Umberto and Fontana, Francesca Arcelli and Taibi, Davide},   booktitle={2019 IEEE/ACM International Conference on Technical Debt (TechDebt)},   pages={88--97},   year={2019},   organization={IEEE} }\",\"  @inproceedings{roveda2018towards,   title={Towards an architectural debt index},   author={Roveda, Riccardo and Fontana, Francesca Arcelli and Pigazzini, Ilaria and Zanoni, Marco},   booktitle={2018 44th Euromicro Conference on Software Engineering and Advanced Applications (SEAA)},   pages={408--416},   year={2018},   organization={IEEE} }\",\"@article{zhong2022impacts,   title={Impacts, causes, and solutions of architectural smells in microservices: An industrial investigation},   author={Zhong, Chenxing and Huang, Huang and Zhang, He and Li, Shanshan},   journal={Software: Practice and Experience},   volume={52},   number={12},   pages={2574--2597},   year={2022},   publisher={Wiley Online Library} }\",\"@inproceedings{pigazzini2019tool,   title={Tool support for the migration to microservice architecture: An industrial case study},   author={Pigazzini, Ilaria and Arcelli Fontana, Francesca and Maggioni, Andrea},   booktitle={Software Architecture: 13th European Conference, ECSA 2019, Paris, France, September 9--13, 2019, Proceedings 13},   pages={247--263},   year={2019},   organization={Springer} }\"]', 'Structure & Infrastructure', 'Structure', 3, 0);
INSERT INTO `antipattern_info` VALUES (109, 'Unstable Dependency', 'Evolutionary coupling', 'It refer to a situation where logical coupling exists between services, resulting in unstable dependencies. Consequently, any changes made to one service will have a cascading effect on other services.', 'Combined judgement based on service dependencies and repository modification history', 'Unstable dependencies between services have several ramifications. Firstly, when a change occurs in one service, it can propagate to other dependent services, leading to a reduction in modularity and analyzability. Moreover, if the introduced change introduces bugs or results in incorrect behavior, it adversely affects the reliability of the entire system.', 'Poor dependency design.', 'In certain cases, a service establishes a direct dependency on the API of another service. Consequently, when changes are made to the API, the dependent service must adapt its code accordingly. For instance, consider the order service, which relies directly on the API of the inventory service to verify the stock level of a product and reduce the stock when creating an order. If the inventory service introduces modifications to the method names or parameters associated with inventory checks, it becomes imperative for the order service to modify its code correspondingly in order to accommodate these changes.', '[\"@inproceedings{azadi2019architectural,   title={Architectural smells detected by tools: a catalogue proposal},   author={Azadi, Umberto and Fontana, Francesca Arcelli and Taibi, Davide},   booktitle={2019 IEEE/ACM International Conference on Technical Debt (TechDebt)},   pages={88--97},   year={2019},   organization={IEEE} }\",\"@inproceedings{roveda2018towards,   title={Towards an architectural debt index},   author={Roveda, Riccardo and Fontana, Francesca Arcelli and Pigazzini, Ilaria and Zanoni, Marco},   booktitle={2018 44th Euromicro Conference on Software Engineering and Advanced Applications (SEAA)},   pages={408--416},   year={2018},   organization={IEEE} }\",\"@inproceedings{fang2023identifying,   title={Identifying Anti-Patterns in Distributed Systems With Heterogeneous Dependencies},   author={Fang, Hongzhou and Cai, Yuanfang and Kazman, Rick and Lefever, Jason},   booktitle={2023 IEEE 20th International Conference on Software Architecture Companion (ICSA-C)},   pages={116--120},   year={2023},   organization={IEEE} }\",\"@article{zhong2022impacts,   title={Impacts, causes, and solutions of architectural smells in microservices: An industrial investigation},   author={Zhong, Chenxing and Huang, Huang and Zhang, He and Li, Shanshan},   journal={Software: Practice and Experience},   volume={52},   number={12},   pages={2574--2597},   year={2022},   publisher={Wiley Online Library} }\",\"@inproceedings{pigazzini2019tool,   title={Tool support for the migration to microservice architecture: An industrial case study},   author={Pigazzini, Ilaria and Arcelli Fontana, Francesca and Maggioni, Andrea},   booktitle={Software Architecture: 13th European Conference, ECSA 2019, Paris, France, September 9--13, 2019, Proceedings 13},   pages={247--263},   year={2019},   organization={Springer} }\"]', 'Structure & Infrastructure', 'Structure', 6, 0);
INSERT INTO `antipattern_info` VALUES (110, 'Implicit Cross-module Dependency', '[\"Implicit cross package dependency\",\"Modularity violation\"]', 'It refer to services that share a common change relationship, despite the absence of explicit dependencies.', 'Combined judgement based on service dependencies and repository modification history', 'The presence of implicit relationships has significant consequences. It diminishes testability, as modifications to one module necessitate corresponding changes in other modules, reducing both modifiability and analyzability. Consequently, clear boundaries between modules are eroded, impeding independent evolution and replacement. This leads to a decreased level of modularity.', 'Poor dependency design.', 'When Service A and Service B share the same configuration file, although they do not communicate directly, changes to the configuration file may affect the behaviour of both services.', '[\"@inproceedings{azadi2019architectural,   title={Architectural smells detected by tools: a catalogue proposal},   author={Azadi, Umberto and Fontana, Francesca Arcelli and Taibi, Davide},   booktitle={2019 IEEE/ACM International Conference on Technical Debt (TechDebt)},   pages={88--97},   year={2019},   organization={IEEE} }\",\"@inproceedings{roveda2018towards,   title={Towards an architectural debt index},   author={Roveda, Riccardo and Fontana, Francesca Arcelli and Pigazzini, Ilaria and Zanoni, Marco},   booktitle={2018 44th Euromicro Conference on Software Engineering and Advanced Applications (SEAA)},   pages={408--416},   year={2018},   organization={IEEE} }\",\"@inproceedings{mo2015hotspot,   title={Hotspot patterns: The formal definition and automatic detection of architecture smells},   author={Mo, Ran and Cai, Yuanfang and Kazman, Rick and Xiao, Lu},   booktitle={2015 12th Working IEEE/IFIP Conference on Software Architecture},   pages={51--60},   year={2015},   organization={IEEE} }\",\"@article{zhong2022impacts,   title={Impacts, causes, and solutions of architectural smells in microservices: An industrial investigation},   author={Zhong, Chenxing and Huang, Huang and Zhang, He and Li, Shanshan},   journal={Software: Practice and Experience},   volume={52},   number={12},   pages={2574--2597},   year={2022},   publisher={Wiley Online Library} }\"]', 'Structure & Infrastructure', 'Structure', 4, 0);
INSERT INTO `antipattern_info` VALUES (111, 'Microservice Greedy', NULL, 'It refers to the practice of dividing unnecessary functions and features into separate services.', 'Comprehensive judgement based on business logic correlations and dependencies between services', ' Introducing unnecessary microservices has several detrimental effects. Firstly, it increases the number of services and complexity of the system, thereby undermining modularity and reducing the system\'s analyzability and maintainability. Additionally, unnecessary functions are transformed into separate services, diminishing reusability. Furthermore, when new functionality or features require modifications across multiple services, it hampers modifiability. The increased communication overhead also limits the system\'s scalability.', 'Blurring of the boundaries of business areas', 'Within an e-commerce platform, two essential services are present: the product search service and the inventory management service. The inventory management service assumes the responsibility of meticulously tracking stock levels and merchandise availability. Conversely, the product search service aims to enhance user experience by filtering search results that are relevant to user-provided keywords. It is worth noting that the functionality of the product search service can be expanded by leveraging the existing inventory management service. Consequently, the creation of a separate product search service is unnecessary in this context.', '[\"@article{taibi2018definition,   title={On the definition of microservice bad smells},   author={Taibi, Davide and Lenarduzzi, Valentina},   journal={IEEE software},   volume={35},   number={3},   pages={56--62},   year={2018},   publisher={IEEE} }\",\"  @article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"@article{zhou2023revisiting,   title={Revisiting the practices and pains of microservice architecture in reality: An industrial inquiry},   author={Zhou, Xin and Li, Shanshan and Cao, Lingli and Zhang, He and Jia, Zijia and Zhong, Chenxing and Shan, Zhihao and Babar, Muhammad Ali},   journal={Journal of Systems and Software},   volume={195},   pages={111521},   year={2023},   publisher={Elsevier} }\",\"  @inproceedings{pulnil2022microservices,   title={A microservices quality model based on microservices anti-patterns},   author={Pulnil, Sermsook and Senivongse, Twittie},   booktitle={2022 19th International Joint Conference on Computer Science and Software Engineering (JCSSE)},   pages={1--6},   year={2022},   organization={IEEE} }\",\"@article{walker2020automated,   title={Automated code-smell detection in microservices through static analysis: A case study},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   journal={Applied Sciences},   volume={10},   number={21},   pages={7800},   year={2020},   publisher={MDPI} }\",\"@inproceedings{walker2021automated,   title={Automated microservice code-smell detection},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   booktitle={Information Science and Applications: Proceedings of ICISA 2020},   pages={211--221},   year={2021},   organization={Springer} }\"]', 'Decomposition ', 'Functionality', 6, 0);
INSERT INTO `antipattern_info` VALUES (112, 'Wrong Cuts', 'Subjective microservices-oriented decomposition without an effective guide', 'It refer to the practice of dividing microservices based on technical layers (representation, business, and data layers) rather than business functions.', 'Comprehensive assessment of service functional responsibilities and granularity size', 'The irrational division of services leads to a surge in complexity and coupling between modules, resulting in a reduction in Modularity, modifiability, analyzability, and scalability. The services become tightly coupled, significantly impacting the system\'s time behavior.', 'The division is not based on reasonable business function boundaries.', 'Suppose we consider an e-commerce application, where the various logic and functions associated with the web interface, including user registration, login, and product display, are consolidated into a single service. Similarly, all the functions related to the business logic, such as order processing, inventory management, payment processing, and more, are encapsulated within a distinct service. Lastly, a separate service is responsible for handling database operations and data storage functions.', '[\"@article{taibi2018definition,   title={On the definition of microservice bad smells},   author={Taibi, Davide and Lenarduzzi, Valentina},   journal={IEEE software},   volume={35},   number={3},   pages={56--62},   year={2018},   publisher={IEEE} }\",\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"@article{zhou2023revisiting,   title={Revisiting the practices and pains of microservice architecture in reality: An industrial inquiry},   author={Zhou, Xin and Li, Shanshan and Cao, Lingli and Zhang, He and Jia, Zijia and Zhong, Chenxing and Shan, Zhihao and Babar, Muhammad Ali},   journal={Journal of Systems and Software},   volume={195},   pages={111521},   year={2023},   publisher={Elsevier} }\",\"@inproceedings{pulnil2022microservices,   title={A microservices quality model based on microservices anti-patterns},   author={Pulnil, Sermsook and Senivongse, Twittie},   booktitle={2022 19th International Joint Conference on Computer Science and Software Engineering (JCSSE)},   pages={1--6},   year={2022},   organization={IEEE} }\",\"@article{walker2020automated,   title={Automated code-smell detection in microservices through static analysis: A case study},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   journal={Applied Sciences},   volume={10},   number={21},   pages={7800},   year={2020},   publisher={MDPI} }\",\"@inproceedings{walker2021automated,   title={Automated microservice code-smell detection},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   booktitle={Information Science and Applications: Proceedings of ICISA 2020},   pages={211--221},   year={2021},   organization={Springer} }\",\"@inproceedings{schirgi2021quality,   title={Quality assurance for microservice architectures},   author={Schirgi, Thomas and Brenner, Eugen},   booktitle={2021 IEEE 12th International Conference on Software Engineering and Service Science (ICSESS)},   pages={76--80},   year={2021},   organization={IEEE} }\"]', 'Decomposition ', 'Functionality', 5, 0);
INSERT INTO `antipattern_info` VALUES (113, 'Duplicated Services', NULL, 'It refer to the presence of a set of services within a microservice system that perform similar or identical functions (semantic duplication), leading to increased redundancy and complexity.', 'Compare the set of functions and operations of different services to determine.', 'The existence of multiple services with the same or similar functions reduces the maintainability of the system. Functional overlap hinders service reuse, thereby diminishing reusability and modularity.', 'Fuzzy business boundaries and a lack of consideration for service reusability.', 'Consider an e-commerce system comprising two microservices: an order service and an inventory service. Unfortunately, due to insufficient communication between teams, the Inventory Service team independently developed a function similar to that of the Order Service, specifically to manage order inventory. Consequently, the system ended up with two services offering comparable functionality, including order creation and inventory deduction, among others. This duplication of services significantly escalated maintenance costs.', '[\"@inproceedings{palma2015study,  title={A study on the taxonomy of service antipatterns},  author={Palma, Francis and Mohay, Naouel},  booktitle={2015 IEEE 2nd International Workshop on Patterns Promotion and Anti-patterns Prevention (PPAP)},  pages={5--8},  year={2015},  organization={IEEE}}\"]', 'Decomposition ', 'Functionality', 5, 0);
INSERT INTO `antipattern_info` VALUES (114, 'Scattered Functionality', NULL, 'It refers to the situation where multiple services are tasked with implementing the same high-level concern, which also encompasses instances where a single service handles multiple concerns. In such cases, there exists a significant level of coupling between services that fulfill the same high-level concern.', 'Analyze and compare the business functional areas and interdependencies among different services to determine.', 'When multiple services address the same high-level concern, modifying one codebase necessitates modifications in other services, reducing modifiability. Additionally, high coupling between modules diminishes modularity.', 'Insufficiently defined service boundaries or inadequate adjustment and refactoring processes in response to business changes and evolution.', 'Consider an e-commerce system with two microservices: an order service and an inventory service. Due to inadequate communication between teams, the inventory service team independently develops a function similar to the order service to handle order inventory management. As a result, the system ends up with two services providing similar functionality, including order creation and inventory deduction. This duplication of services significantly escalates maintenance costs.', '[\"@inproceedings{azadi2019architectural,   title={Architectural smells detected by tools: a catalogue proposal},   author={Azadi, Umberto and Fontana, Francesca Arcelli and Taibi, Davide},   booktitle={2019 IEEE/ACM International Conference on Technical Debt (TechDebt)},   pages={88--97},   year={2019},   organization={IEEE} }\",\"@article{zhong2022impacts,   title={Impacts, causes, and solutions of architectural smells in microservices: An industrial investigation},   author={Zhong, Chenxing and Huang, Huang and Zhang, He and Li, Shanshan},   journal={Software: Practice and Experience},   volume={52},   number={12},   pages={2574--2597},   year={2022},   publisher={Wiley Online Library} }\"]', 'Decomposition ', 'Functionality', 2, 0);
INSERT INTO `antipattern_info` VALUES (115, 'Nobody Home', 'Retiring components', 'It refers to the existence of services that are not being used in a microservices system.', 'Perform a statistical analysis to identify services that remain unused by analyzing runtime service call logs.', 'Deploying and managing services that are never utilized imposes additional maintenance costs and diminishes the overall maintainability of the system. The presence of a substantial number of unused services, irrespective of containerized deployment, can detrimentally impact the performance efficiency of the system.', 'Business change or it is incorrectly classified as a separate microservice.', 'Consider an e-commerce system comprising multiple microservices, such as user service, order service, inventory service, and payment service. However, during the system\'s evolution, it becomes evident that the payment service remains unused by both other services and clients. In the initial stages of system design, the payment service may have been deemed essential due to its role in processing order payments. Nevertheless, as business requirements change over time, such as a decision to outsource payment processing to a third-party provider, the payment service becomes obsolete but is not updated or removed accordingly.', '[\"@article{palma2018unidosa,   title={UniDoSA: the unified specification and detection of service antipatterns},   author={Palma, Francis and Moha, Naouel and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   journal={IEEE Transactions on Software Engineering},   volume={45},   number={10},   pages={1024--1053},   year={2018},   publisher={IEEE} }\",\"  @inproceedings{palma2014investigating,   title={Investigating the change-proneness of service patterns and antipatterns},   author={Palma, Francis and An, Le and Khomh, Foutse and Moha, Naouel and Gu{\\\\\'e}h{\\\\\'e}neuc, Yann-Ga{\\\"e}l},   booktitle={2014 IEEE 7th International Conference on Service-Oriented Computing and Applications},   pages={1--8},   year={2014},   organization={IEEE} }\",\"@inproceedings{fang2023identifying,   title={Identifying Anti-Patterns in Distributed Systems With Heterogeneous Dependencies},   author={Fang, Hongzhou and Cai, Yuanfang and Kazman, Rick and Lefever, Jason},   booktitle={2023 IEEE 20th International Conference on Software Architecture Companion (ICSA-C)},   pages={116--120},   year={2023},   organization={IEEE} }\"]', 'Decomposition ', 'Functionality', 8, 0);
INSERT INTO `antipattern_info` VALUES (116, 'Sharing Persistence', '[\"Unplanned data sharing\"，\"Shared database\"]', 'It refers to the situation where multiple services share a common database.', 'Extraction of database connection information from each service is necessary to determine the details of database usage.', 'Modifying the data model requires making changes to entities across multiple services, thereby reducing modifiability, increasing system complexity, and diminishing modularity. There may also be data coupling between different services, leading to increased coupling. This, in turn, raises the risk of data leakage, compromising confidentiality. Furthermore, if the shared database experiences failures or performance issues, all services relying on it will be adversely affected, reducing fault tolerance.', ' The principle of independence and autonomy of services has not been adequately considered.', 'The user service and the order service both utilize the same database instance. Consequently, in the event of a security breach occurring in one service, the data of the other service is also susceptible to compromise.', '[\"@article{de2021identifying,   title={Identifying architectural technical debt, principal, and interest in microservices: A multiple-case study},   author={de Toledo, Saulo S and Martini, Antonio and Sj{\\\\o}berg, Dag IK},   journal={Journal of Systems and Software},   volume={177},   pages={110968},   year={2021},   publisher={Elsevier} }\",\" @article{taibi2018definition,   title={On the definition of microservice bad smells},   author={Taibi, Davide and Lenarduzzi, Valentina},   journal={IEEE software},   volume={35},   number={3},   pages={56--62},   year={2018},   publisher={IEEE} }\",\"@article{de2022accumulation,   title={Accumulation and prioritization of architectural debt in three companies migrating to microservices},   author={De Toledo, Saulo Soares and Martini, Antonio and Nguyen, Phu H and Sj{\\\\o}berg, Dag IK},   journal={IEEE Access},   volume={10},   pages={37422--37445},   year={2022},   publisher={IEEE} }\",\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"  @inproceedings{pigazzini2020towards,   title={Towards microservice smells detection},   author={Pigazzini, Ilaria and Fontana, Francesca Arcelli and Lenarduzzi, Valentina and Taibi, Davide},   booktitle={Proceedings of the 3rd International Conference on Technical Debt},   pages={92--97},   year={2020} }\",\"@inproceedings{pulnil2022microservices,   title={A microservices quality model based on microservices anti-patterns},   author={Pulnil, Sermsook and Senivongse, Twittie},   booktitle={2022 19th International Joint Conference on Computer Science and Software Engineering (JCSSE)},   pages={1--6},   year={2022},   organization={IEEE} }\",\"  @article{walker2020automated,   title={Automated code-smell detection in microservices through static analysis: A case study},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   journal={Applied Sciences},   volume={10},   number={21},   pages={7800},   year={2020},   publisher={MDPI} }\",\"@inproceedings{walker2021automated,   title={Automated microservice code-smell detection},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   booktitle={Information Science and Applications: Proceedings of ICISA 2020},   pages={211--221},   year={2021},   organization={Springer} }\",\"@inproceedings{brogi2020freshening,   title={Freshening the air in microservices: Resolving architectural smells via refactoring},   author={Brogi, Antonio and Neri, Davide and Soldani, Jacopo},   booktitle={Service-Oriented Computing--ICSOC 2019 Workshops: WESOACS, ASOCA, ISYCC, TBCE, and STRAPS, Toulouse, France, October 28--31, 2019, Revised Selected Papers 17},   pages={17--29},   year={2020},   organization={Springer} }\",\"@inproceedings{bacchiega2022microservices,   title={Microservices smell detection through dynamic analysis},   author={Bacchiega, Paolo and Pigazzini, Ilaria and Fontana, Francesca Arcelli},   booktitle={2022 48th Euromicro Conference on Software Engineering and Advanced Applications (SEAA)},   pages={290--293},   year={2022},   organization={IEEE} }\",\"@inproceedings{schirgi2021quality,   title={Quality assurance for microservice architectures},   author={Schirgi, Thomas and Brenner, Eugen},   booktitle={2021 IEEE 12th International Conference on Software Engineering and Service Science (ICSESS)},   pages={76--80},   year={2021},   organization={IEEE} }\"]', 'Decomposition ', 'Service Data Management', 4, 0);
INSERT INTO `antipattern_info` VALUES (117, 'Inappropriate Service Intimacy', NULL, 'It refers to the situation where a service accesses the private data of other services in addition to its own private data.', 'Extract the database connection information of each service to determine.', 'Modifications to the data model necessitate making changes to entities across multiple services, thereby diminishing modifiability, increasing system complexity, and reducing modularity. Data coupling between services intensifies the coupling between them. Unauthorized access to private data of other services can easily result in data leakage and compromise confidentiality. In the event of database failures or performance issues, all services reliant on the database will be impacted, reducing fault tolerance.', 'The principle of service independence and autonomy has not been fully considered.', 'An order service may require access to private data, such as user information, from a user service in order to associate user details with the order during its creation.', '[\"@article{taibi2018definition,   title={On the definition of microservice bad smells},   author={Taibi, Davide and Lenarduzzi, Valentina},   journal={IEEE software},   volume={35},   number={3},   pages={56--62},   year={2018},   publisher={IEEE} }\",\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"  @inproceedings{pulnil2022microservices,   title={A microservices quality model based on microservices anti-patterns},   author={Pulnil, Sermsook and Senivongse, Twittie},   booktitle={2022 19th International Joint Conference on Computer Science and Software Engineering (JCSSE)},   pages={1--6},   year={2022},   organization={IEEE} }\",\"@article{walker2020automated,   title={Automated code-smell detection in microservices through static analysis: A case study},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   journal={Applied Sciences},   volume={10},   number={21},   pages={7800},   year={2020},   publisher={MDPI} }\",\"@inproceedings{walker2021automated,   title={Automated microservice code-smell detection},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   booktitle={Information Science and Applications: Proceedings of ICISA 2020},   pages={211--221},   year={2021},   organization={Springer} }\"]', 'Decomposition ', 'Service Data Management', 4, 0);
INSERT INTO `antipattern_info` VALUES (118, 'Own Crypto Code', NULL, 'Development teams employ their proprietary encryption solutions and algorithms.', 'The determination is made by reviewing the encryption-related code.', 'The utilization of poorly defined solutions can be counterproductive, potentially worse than having no cryptographic solution at all. This situation creates a false sense of security and compromises the system\'s confidentiality, integrity, and authenticity.', 'Adequate testing of custom encryption algorithms not considered.', 'The team might have developed a proprietary cryptographic library named \"CustomCrypto,\" encompassing their own designed cryptographic algorithms and associated functions. This custom crypto library is utilized within microservices to encrypt sensitive data, including user passwords and payment information. However, the security of the cryptographic algorithm may not have undergone sufficient auditing and validation, rendering the system vulnerable to potential attacks.', '[\"@book{hofmann2017microservices,   title={Microservices best practices for Java},   author={Hofmann, Michael and Schnabel, Erin and Stanley, Katherine and others},   year={2017},   publisher={IBM Redbooks} }\",\"@article{dell2023kubehound,   title={KubeHound: Detecting Microservices’ Security Smells in Kubernetes Deployments},   author={Dell’Immagine, Giorgio and Soldani, Jacopo and Brogi, Antonio},   journal={Future Internet},   volume={15},   number={7},   pages={228},   year={2023},   publisher={MDPI} }\"]', 'Security', 'Data and Communication', 3, 0);
INSERT INTO `antipattern_info` VALUES (119, 'Non-encrypted Data Exposure', NULL, 'It refers to a situation where sensitive data is transmitted or stored without encryption, leading to inadvertent exposure of such information. The focus is primarily on message-level security concerns.', 'The determination is made based on whether the microservice incorporates standard encryption-related libraries and frameworks.', 'Once sensitive data is exposed, it becomes susceptible to unauthorized access and modification, thereby compromising the system\'s confidentiality and integrity.', 'Insufficient security awareness.', 'If an e-commerce platform system neglects to encrypt sensitive data, including users\' personal information, payment details, and order data, it exposes a significant vulnerability. In such a scenario, an attacker could gain unauthorized access to and pilfer users\' personal information, thereby posing a substantial risk of identity theft, fraud, and other malicious activities.', '[\"@book{hofmann2017microservices,   title={Microservices best practices for Java},   author={Hofmann, Michael and Schnabel, Erin and Stanley, Katherine and others},   year={2017},   publisher={IBM Redbooks} }\", \"@book{dias2020microservices,   title={Microservices security in action},   author={Dias, Wajjakkara Kankanamge Anthony Nuwan and Siriwardena, Prabath},   year={2020},   publisher={Simon and Schuster} }\", \"@article{dell2023kubehound,   title={KubeHound: Detecting Microservices’ Security Smells in Kubernetes Deployments},   author={Dell’Immagine, Giorgio and Soldani, Jacopo and Brogi, Antonio},   journal={Future Internet},   volume={15},   number={7},   pages={228},   year={2023},   publisher={MDPI} }\"]', 'Security', 'Data and Communication', 2, 0);
INSERT INTO `antipattern_info` VALUES (120, 'Hardcoded Secrets', NULL, 'It refers to a situation where hard-coded credentials exist within the microservice source code or environment variables, with the key value being present in the deployment script.', 'Detection involves scanning the source code and deployment script files to identify unencrypted API keys, database keys, and other related information.', 'Storing keys within source code or environment variables renders the confidentiality and integrity of the system vulnerable to breaches if they are inadvertently exposed.', 'Lack of a comprehensive credential management policy.', 'If the database connection key of a microservice is exposed within an environment variable in a k8s deployment script, and the script is leaked, the private data stored in the database becomes susceptible to unauthorized access and potential corruption.', '[\"@book{hofmann2017microservices,   title={Microservices best practices for Java},   author={Hofmann, Michael and Schnabel, Erin and Stanley, Katherine and others},   year={2017},   publisher={IBM Redbooks} }\",\"@article{dell2023kubehound,   title={KubeHound: Detecting Microservices’ Security Smells in Kubernetes Deployments},   author={Dell’Immagine, Giorgio and Soldani, Jacopo and Brogi, Antonio},   journal={Future Internet},   volume={15},   number={7},   pages={228},   year={2023},   publisher={MDPI} }\"]', 'Security', 'Data and Communication', 2, 0);
INSERT INTO `antipattern_info` VALUES (121, 'Non-secured Service-to-service Communications', NULL, 'It refers  to the situation where secure interaction is lacking between microservices, with a particular focus on transport layer security issues.', 'Detection involves a comprehensive assessment of encrypted communication, authentication-related function calls, library references, the utilization of security frameworks in the source code, and protocol configuration items in the configuration file.', 'The absence of secure inter-service communication compromises the confidentiality, integrity, and authenticity of transmitted data. It becomes susceptible to tampering, leading to potential data manipulation and inaccurate payment amounts.', 'Failure to consider the security aspects of service interaction.', 'The interaction between the order service and the payment service occurs in plaintext without authentication and data encryption. This security vulnerability exposes the order data to potential tampering, compromising its integrity. Furthermore, the lack of encryption leads to inaccuracies in the payment amount, undermining the reliability of the transaction.', '[\"@book{hofmann2017microservices,   title={Microservices best practices for Java},   author={Hofmann, Michael and Schnabel, Erin and Stanley, Katherine and others},   year={2017},   publisher={IBM Redbooks} }\",\"@book{carnell2021spring,   title={Spring microservices in action},   author={Carnell, John and S{\\\\\'a}nchez, Illary Huaylupo},   year={2021},   publisher={Simon and Schuster} }\",\"@book{dias2020microservices,   title={Microservices security in action},   author={Dias, Wajjakkara Kankanamge Anthony Nuwan and Siriwardena, Prabath},   year={2020},   publisher={Simon and Schuster} }\",\"@article{dell2023kubehound,   title={KubeHound: Detecting Microservices’ Security Smells in Kubernetes Deployments},   author={Dell’Immagine, Giorgio and Soldani, Jacopo and Brogi, Antonio},   journal={Future Internet},   volume={15},   number={7},   pages={228},   year={2023},   publisher={MDPI} }\"]', 'Security', 'Data and Communication', 3, 0);
INSERT INTO `antipattern_info` VALUES (122, 'Insufficient Access Control', NULL, 'It refers to microservices that lack adequate access rights control, thereby compromising the security of the system.', 'Detection involves scanning the source code to assess the effectiveness of the business logic for access rights control.', 'The attacker obtains data that should not have been obtained, and the confidentiality of the system is compromised.', 'Failure to establish appropriate access control mechanisms.', 'Within a healthcare microservices system, the medical record service lacks sufficient access control. This vulnerability allows an attacker to obtain sensitive personal medical information, such as disease diagnoses, drug prescriptions, and surgical records, which should have remained confidential.', '[\"@article{dell2023kubehound,   title={KubeHound: Detecting Microservices’ Security Smells in Kubernetes Deployments},   author={Dell’Immagine, Giorgio and Soldani, Jacopo and Brogi, Antonio},   journal={Future Internet},   volume={15},   number={7},   pages={228},   year={2023},   publisher={MDPI} }\"]', 'Security', 'Authentication and Authorization', 1, 0);
INSERT INTO `antipattern_info` VALUES (123, 'Publicly Accessible Microservices', NULL, 'Microservices can be accessed directly by external clients.', 'Determination is made based on the presence of an API gateway or similar mechanisms.', 'Client direct connect service reduces system confidentiality', 'Insufficient awareness of security risks.', 'Publicly accessible microservices expose api endpoint information, exposing the system to potential security risks.', '[\"@book{pacheco2018microservice,   title={Microservice Patterns and Best Practices: Explore patterns like CQRS and event sourcing to create scalable, maintainable, and testable microservices},   author={Pacheco, Vinicius Feitosa},   year={2018},   publisher={Packt Publishing Ltd} }\",\"@article{dell2023kubehound,   title={KubeHound: Detecting Microservices’ Security Smells in Kubernetes Deployments},   author={Dell’Immagine, Giorgio and Soldani, Jacopo and Brogi, Antonio},   journal={Future Internet},   volume={15},   number={7},   pages={228},   year={2023},   publisher={MDPI} }\"]', 'Security', 'Authentication and Authorization', 1, 0);
INSERT INTO `antipattern_info` VALUES (124, 'Unnecessary Privileges To Microservices', NULL, 'It refers to a situation where microservices are granted unnecessary privileges.', 'Comprehensive judgement based on the service\'s business logic and authorisation policy.', 'Consequence: When microservices are granted unnecessary privileges, they can access and expose sensitive information unrelated to their responsibilities, which can lead to confidentiality  and integrity issues.', 'Lack of adoption of the principle of least privilege.', 'A user management microservice is granted access to order data and inventory data when in reality it only needs to handle user-related functionality, so there is an unnecessary privilege issue.', '[\"@book{carnell2021spring,   title={Spring microservices in action},   author={Carnell, John and S{\\\\\'a}nchez, Illary Huaylupo},   year={2021},   publisher={Simon and Schuster} }\",\"@article{dell2023kubehound,   title={KubeHound: Detecting Microservices’ Security Smells in Kubernetes Deployments},   author={Dell’Immagine, Giorgio and Soldani, Jacopo and Brogi, Antonio},   journal={Future Internet},   volume={15},   number={7},   pages={228},   year={2023},   publisher={MDPI} }\"]', 'Security', 'Authentication and Authorization', 2, 0);
INSERT INTO `antipattern_info` VALUES (125, 'Unauthenticated Traffic', NULL, 'It refers to the situation in which unauthenticated requests originate from external sources or occur among microservices.', 'Scanning the source code to analyse whether it incorporates authentication logic.', 'When there is a lack of proper authentication mechanisms between microservices and between external sources and services, it can lead to authenticity issues.', 'Lack of adoption of the appropriate authentication mechanism.', 'If an order management microservice accepts unauthenticated requests from external sources or receives unauthenticated requests through internal communications, it gives rise to an unauthenticated traffic problem. This implies that any unauthenticated user or system could gain access to the order management', '[\"@book{hofmann2017microservices,   title={Microservices best practices for Java},   author={Hofmann, Michael and Schnabel, Erin and Stanley, Katherine and others},   year={2017},   publisher={IBM Redbooks} }\",\"@article{dell2023kubehound,   title={KubeHound: Detecting Microservices’ Security Smells in Kubernetes Deployments},   author={Dell’Immagine, Giorgio and Soldani, Jacopo and Brogi, Antonio},   journal={Future Internet},   volume={15},   number={7},   pages={228},   year={2023},   publisher={MDPI} }\"]', 'Security', 'Authentication and Authorization', 1, 0);
INSERT INTO `antipattern_info` VALUES (126, 'Multiple User Authentication', NULL, 'It refers to the situation in which a microservice system utilizes multiple access points to manage user authentication and authorization.', 'Scanning the source code to analyse whether it contains multiple authentication logic.', 'Employing multiple access points for authentication can result in authenticity issues.', 'Lack of a single sign-on mechanism.', 'Within an e-commerce microservice system, there may exist multiple access points responsible for handling authentication and access rights control for ordinary users, merchant users, and administrator users, respectively. This approach expands the system\'s attack surface and increases security risks.', '[\"@book{hofmann2017microservices,   title={Microservices best practices for Java},   author={Hofmann, Michael and Schnabel, Erin and Stanley, Katherine and others},   year={2017},   publisher={IBM Redbooks} }\",\"@article{dell2023kubehound,   title={KubeHound: Detecting Microservices’ Security Smells in Kubernetes Deployments},   author={Dell’Immagine, Giorgio and Soldani, Jacopo and Brogi, Antonio},   journal={Future Internet},   volume={15},   number={7},   pages={228},   year={2023},   publisher={MDPI} }\"]', 'Security', 'Authentication and Authorization', 1, 0);
INSERT INTO `antipattern_info` VALUES (127, 'Centralized Authorization', NULL, 'It refers to the situation in which authorization decisions and access control logic are consolidated within a centralized component or service.', 'Identification is based on the presence of identity authorization logic within multiple services.', 'If a problem arises within the centralized component or service responsible for authorization, it can result in authorization and access control failures, thereby impacting authenticity.', 'The failure to consider distributed authorization schemes.', 'For instance, consider a microservices system where centralized authorization is employed to manage access to sensitive data. The gateway service assumes the responsibility of user authentication and controls their access to individual microservices. However, as a result of a design or configuration flaw, a vulnerability is present within the authorization logic of the gateway service. An attacker leverages this vulnerability and successfully bypasses authorization validation, thereby gaining direct access to microservices containing sensitive data.', '[\"@book{hofmann2017microservices,   title={Microservices best practices for Java},   author={Hofmann, Michael and Schnabel, Erin and Stanley, Katherine and others},   year={2017},   publisher={IBM Redbooks} }\",\"@article{dell2023kubehound,   title={KubeHound: Detecting Microservices’ Security Smells in Kubernetes Deployments},   author={Dell’Immagine, Giorgio and Soldani, Jacopo and Brogi, Antonio},   journal={Future Internet},   volume={15},   number={7},   pages={228},   year={2023},   publisher={MDPI} }\"]', 'Security', 'Authentication and Authorization', 1, 0);
INSERT INTO `antipattern_info` VALUES (128, 'Nonhomogeneous Adoption', NULL, 'it refers to a situation where only a few teams opt to migrate to microservices, and the decision to migrate or not is made solely by the development team.', 'Determination is based on the extent of microservice adoption across the entire system.', 'The system consists of both monolithic and microservice architecture components, which poses challenges in terms of deployment and installation, thereby diminishing the overall installability of the system.', 'Insufficient comprehensive organizational planning.', 'For instance, consider a company where the order management team decides to migrate their order management functionality to a microservices architecture. They create a standalone order management microservice along with its corresponding database. Embracing modern technology stack and adhering to best practices, they utilize containerization and automated deployment to facilitate continuous integration and continuous delivery. However, other teams, such as the user management team and the product catalogue team, choose to maintain the traditional monolithic architecture and a shared database. These teams perceive the migration to microservices as introducing excessive complexity and risk, and thus opt to retain the status quo. Consequently, the company\'s technology stack and architecture become inconsistent. The order management team employs distinct technologies and tools for their microservices, while the other teams continue with the conventional monolithic development approach. This disparity leads to inconsistencies in the development and deployment processes.', '[\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\"]', 'Lifecycle Management', 'Migration', 1, 0);
INSERT INTO `antipattern_info` VALUES (129, 'Local Logging', NULL, 'It refers to the situation in which logs generated by each microservice are stored locally, resulting in the absence of a unified distributed logging mechanism for centralizing monitoring and analysis of microservice systems.', 'Detection is performed by analyzing the log collection and transmission methods employed by the system, specifically by examining whether log collection-related dependencies are present in the system\'s dependency files.', 'When logs are dispersed and stored locally within each microservice, the loss of related logs may occur if a microservice fails or crashes. This hinders the ability to trace and diagnose failures, consequently reducing system reliability. Additionally, the absence of a centralized, unified view to analyze log data from all microservices diminishes the system\'s analyzability.', 'Lack of a unified log management strategy.', 'Within an e-commerce microservice system, each microservice employs its own logging mechanism to store logs in local files or databases. For instance, the user management microservice records user login and registration information in its respective local log file, while the order management microservice stores order creation and update logs in its own local log file. As each microservice has its independent log storage, real-time monitoring of the entire system\'s operational status becomes unattainable, thereby limiting comprehensive understanding of system behavior and performance issues.', '[\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"@article{zhou2023revisiting,   title={Revisiting the practices and pains of microservice architecture in reality: An industrial inquiry},   author={Zhou, Xin and Li, Shanshan and Cao, Lingli and Zhang, He and Jia, Zijia and Zhong, Chenxing and Shan, Zhihao and Babar, Muhammad Ali},   journal={Journal of Systems and Software},   volume={195},   pages={111521},   year={2023},   publisher={Elsevier} }\"]', 'Lifecycle Management', 'Deployment', 5, 0);
INSERT INTO `antipattern_info` VALUES (130, 'Multiple Services Per Deployment Unit', NULL, 'It  refers to the situation where multiple instances of microservices are deployed on a single node or container, resulting in the sharing of resources among these instances.', 'Determination is made based on the deployment strategy employed for the services.', 'When multiple instances share the resources of a single host or node, it negatively impacts the performance efficiency and adaptability of the system under high load conditions. Additionally, the interaction between service instances reduces the modularity of the system.', 'The failure to isolate each service and adhere to the principle of autonomy.', 'In an e-commerce microservice system, all service instances are deployed on the same node without utilizing containerized deployment. There may be technical conflict issues between service instances.', '[\"@inproceedings{soldani2023kubernetes,   title={Kubernetes-Enabled Detection and Resolution of Architectural Smells for Microservices},   author={Soldani, Jacopo and Rendina, Davide and Fontana, Francesca Arcelli and Brogi, Antonio},   booktitle={2023 IEEE International Conference on Service-Oriented System Engineering (SOSE)},   pages={75--80},   year={2023},   organization={IEEE} }\"]', 'Lifecycle Management', 'Deployment', 5, 0);
INSERT INTO `antipattern_info` VALUES (131, 'Manual Configuration', NULL, 'It refers to the situation where the service configuration is manually performed by the developer.', 'Detection involves identifying the presence of code that interacts with the configuration server, followed by making subsequent determinations.', 'The manual configuration process for microservices is highly time-consuming and prone to errors, thereby diminishing fault tolerance.', 'Lack of utilizing a configuration server to automate the configuration process.', 'Consider a web application comprised of multiple microservices. In the case of manual configuration, developers are required to manually modify the configuration file or code for each microservice to configure its runtime behavior.', '[\"@inproceedings{schirgi2021quality,   title={Quality assurance for microservice architectures},   author={Schirgi, Thomas and Brenner, Eugen},   booktitle={2021 IEEE 12th International Conference on Software Engineering and Service Science (ICSESS)},   pages={76--80},   year={2021},   organization={IEEE} }\"]', 'Lifecycle Management', 'Deployment', 1, 0);
INSERT INTO `antipattern_info` VALUES (132, 'Single DevOps Toolchain', NULL, 'It refers to the situation where each microservice lacks a separate DevOps toolchain and instead utilizes the same pipeline, thereby violating the principle of service autonomy.', 'Detection involves checking for the presence of unified build scripts, deployment configurations, and other related factors.', 'When a common pipeline is employed for all microservices, it restricts the autonomy of each service and diminishes its modularity. Additionally, services may encounter shared limitations during the build, deployment, and maintenance processes, thereby reducing maintainability.', 'The absence of establishing a separate pipeline for each service, thus compromising autonomy.', 'All microservices might rely on a shared version control system, such as git, and employ identical build tools like jenkins. Additionally, they may utilize the same deployment tools like docker and kubernetes, as well as monitoring tools such as Prometheus and Grafana. In this setup, the code and configuration for each microservice are stored within a single code repository, and they share a common deployment and monitoring process. Consequently, the autonomy of individual microservices is compromised.', '[\"@article{balalaie2018microservices,   title={Microservices migration patterns},   author={Balalaie, Armin and Heydarnoori, Abbas and Jamshidi, Pooyan and Tamburri, Damian A and Lynn, Theo},   journal={Software: Practice and Experience},   volume={48},   number={11},   pages={2019--2042},   year={2018},   publisher={Wiley Online Library} }\"]', 'Lifecycle Management', 'Deployment', 6, 0);
INSERT INTO `antipattern_info` VALUES (133, 'Insufficient Monitoring', 'Lack of monitoring', 'Microservices are bound by Service Level Agreements (SLAs), making the monitoring of their behavior crucial. Insufficient service monitoring exacerbates maintenance difficulties and hinders fault localization.', 'Further determination is contingent upon the monitoring strategy implemented for the entire system.', ' Inadequate monitoring of the complete system curtails reliability and maintainability. Insufficient monitoring impedes the modification and evolution of the microservices system, thereby reducing modifiability and analyzability. Moreover, the absence of monitoring can result in misconfigurations, incompatible environments, or conflicting dependencies during the installation process, adversely affecting the system\'s installability.', 'Lack of monitoring policies and tools.', 'In a microservices system, only local execution logs are available for each service, without the implementation of other monitoring strategies. Consequently, when a failure occurs, it becomes arduous to trace the root cause, severely limiting the system\'s maintainability.', '[\"@article{balalaie2018microservices,   title={Microservices migration patterns},   author={Balalaie, Armin and Heydarnoori, Abbas and Jamshidi, Pooyan and Tamburri, Damian A and Lynn, Theo},   journal={Software: Practice and Experience},   volume={48},   number={11},   pages={2019--2042},   year={2018},   publisher={Wiley Online Library} }\",\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"  @article{zhou2023revisiting,   title={Revisiting the practices and pains of microservice architecture in reality: An industrial inquiry},   author={Zhou, Xin and Li, Shanshan and Cao, Lingli and Zhang, He and Jia, Zijia and Zhong, Chenxing and Shan, Zhihao and Babar, Muhammad Ali},   journal={Journal of Systems and Software},   volume={195},   pages={111521},   year={2023},   publisher={Elsevier} }\",\"@inproceedings{schirgi2021quality,   title={Quality assurance for microservice architectures},   author={Schirgi, Thomas and Brenner, Eugen},   booktitle={2021 IEEE 12th International Conference on Software Engineering and Service Science (ICSESS)},   pages={76--80},   year={2021},   organization={IEEE} }\"]', 'Lifecycle Management', 'Operations', 10, 0);
INSERT INTO `antipattern_info` VALUES (134, 'Manual Per Service Handling Of Network Failures', NULL, 'It refers to the situation where the unavailability of the target service is manually resolved by redirecting it to an available service instance.', 'Detection is based on whether the microservice utilizes an easy orchestration and management system, such as Kubernetes.', 'The complexity of maintenance increases as manual intervention is required to address faults, potentially prolonging the system\'s recovery time and reducing its availability. Human intervention introduces the risk of errors, thereby diminishing system reliability. Additionally, the absence of automated containerized orchestration and management leads to increased system maintenance costs and reduced maintainability.', 'The failure to adopt containerized orchestration and management to automatically handle the failure of container instances.', 'In an e-commerce microservice system, the order instance relies on the payment instance to process payments. If the payment instance fails, the current request cannot be handled, necessitating manual redeployment of the payment instance and causing unnecessary inconvenience.', '[\"@article{de2021identifying,   title={Identifying architectural technical debt, principal, and interest in microservices: A multiple-case study},   author={de Toledo, Saulo S and Martini, Antonio and Sj{\\\\o}berg, Dag IK},   journal={Journal of Systems and Software},   volume={177},   pages={110968},   year={2021},   publisher={Elsevier} }\"]', 'Lifecycle Management', 'Operations', 9, 0);
INSERT INTO `antipattern_info` VALUES (135, 'Weak Source Code And Knowledge Management', NULL, 'It refers to the lack of source code and knowledge management for different services.', 'Detection is based on whether each service utilizes a repository for source code management.', 'Inadequate source code management can lead to code that is difficult to trace, diminishing analyzability. Developers may lack awareness of the code\'s function, purpose, and dependencies, making it challenging to improve and reducing maintainability and modifiability. The system becomes challenging to expand, weakening adaptability and increasing the complexity of introducing new features. Additionally, the absence of proper code organization and documentation hinders developers\' understanding of the existing code structure and design, deteriorating code learnability.', 'Lack of organizational awareness regarding the importance of source code and knowledge management.', 'Consider an e-commerce microservices system where all services are currently at version 2.1. If a sudden issue arises with the v2.1 version of the order service, analyzing the failure requires comparing it to the previous version of the code. Without a repository, conducting such analysis becomes arduous.', '[\"@inproceedings{de2019architectural,   title={Architectural technical debt in microservices: a case study in a large company},   author={De Toledo, Saulo Soares and Martini, Antonio and Przybyszewska, Agata and Sj{\\\\o}berg, Dag IK},   booktitle={2019 IEEE/ACM International Conference on Technical Debt (TechDebt)},   pages={78--87},   year={2019},   organization={IEEE} }\"]', 'Lifecycle Management', 'Operations', 7, 0);
INSERT INTO `antipattern_info` VALUES (136, 'No Continuous Integration / Continuous Delivery (CI/CD)', '[\"No DevOps tools\"，\"Microservices DevOps\"，\"Inadequate automation\"]', 'It refers to the lack of practices or processes forCI/CD. CI/CD is a software development practice aimed at facilitating fast, frequent, and reliable software delivery by automating build, test, and deployment procedures.', 'Detection involves checking for the presence of an automated build profile, such as a jenkinsfile.', 'The lack of CI/CD, coupled with intricate dependencies between services, increases the complexity of manual deployment and diminishes installability. Manual execution of build, test, and deployment tasks is prone to human errors, reducing the system\'s fault tolerance, escalating time costs, and affecting its time behavior.', 'Failure to recognize the significance of implementing CI/CD.', 'Teams rely on manual deployment processes for each software update or release. This process entails manual file copying, server configuration, manual script execution, and so forth. Such manual deployment practices are susceptible to errors, time-consuming, and unreliable.', '[\"@inproceedings{brown2016implementation,   title={Implementation patterns for microservices architectures},   author={Brown, Kyle and Woolf, Bobby},   booktitle={Proceedings of the 23rd conference on pattern languages of programs},   pages={1--35},   year={2016} }\",\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"@article{zhou2023revisiting,   title={Revisiting the practices and pains of microservice architecture in reality: An industrial inquiry},   author={Zhou, Xin and Li, Shanshan and Cao, Lingli and Zhang, He and Jia, Zijia and Zhong, Chenxing and Shan, Zhihao and Babar, Muhammad Ali},   journal={Journal of Systems and Software},   volume={195},   pages={111521},   year={2023},   publisher={Elsevier} }\",\"@inproceedings{schirgi2021quality,   title={Quality assurance for microservice architectures},   author={Schirgi, Thomas and Brenner, Eugen},   booktitle={2021 IEEE 12th International Conference on Software Engineering and Service Science (ICSESS)},   pages={76--80},   year={2021},   organization={IEEE} }\"]', 'Lifecycle Management', 'Operations', 3, 0);
INSERT INTO `antipattern_info` VALUES (137, 'No Health Check', NULL, 'Microservices exhibit flexibility and volatility, being deployable anywhere and susceptible to unavailability in specific times or contexts. In the absence of a health check mechanism, the sudden unavailability of a service instance can result in prolonged waiting periods for dependent services.', 'Determine whether a health check mechanism is used by detecting whether relevant dependencies (consul, zookeeper, etcd, eureka, linkerd, etc.) have been introduced', 'Failure to promptly detect failures or anomalies hinders the system from functioning correctly, thereby diminishing the system\'s availability.', 'Neglecting the importance of implementing health checks.', 'In a booking system, the lack of health checks for the authentication service can impact other microservices dependent on it. Without accurate information on the service\'s availability, errors or unexpected behaviors may occur.', '[\"@inproceedings{schirgi2021quality,   title={Quality assurance for microservice architectures},   author={Schirgi, Thomas and Brenner, Eugen},   booktitle={2021 IEEE 12th International Conference on Software Engineering and Service Science (ICSESS)},   pages={76--80},   year={2021},   organization={IEEE} }\"]', 'Lifecycle Management', 'Operations', 1, 0);
INSERT INTO `antipattern_info` VALUES (138, 'Team Coupling', NULL, 'It refers to the practice of dividing the microservices system into teams based on technical layers. Changes made to the microservices may require cross-team approvals, resulting in significant inconvenience during the development and optimization process.', 'Detection is determined by assessing the contribution of different development teams to the codebase.', 'Even simple changes to the business logic may necessitate cross-team approval, affecting the system\'s time behavior. Organizing teams based on technology layers instead of business functions hampers timely interactions between teams, thereby impeding the modularity of services.', 'The organizational structure driven by technology considerations.', 'Team members are restricted to making changes and releases solely within their assigned technical layer, thereby lacking autonomy and responsibility for other technical layers. This limitation hinders the team\'s ability to independently optimize and improve microservices.', '[\"@inproceedings{fang2023identifying,   title={Identifying Anti-Patterns in Distributed Systems With Heterogeneous Dependencies},   author={Fang, Hongzhou and Cai, Yuanfang and Kazman, Rick and Lefever, Jason},   booktitle={2023 IEEE 20th International Conference on Software Architecture Companion (ICSA-C)},   pages={116--120},   year={2023},   organization={IEEE} }\"]', 'Team & Technology', 'Team ', 2, 0);
INSERT INTO `antipattern_info` VALUES (139, 'Common Ownership', NULL, 'It refers to the situation where a single team is responsible for the development of the entire microservice system, rather than assigning different microservices to separate teams for independent development and maintenance. Consequently, all teams work within the same development and deployment pipeline, which fails to fully reflect the independence and autonomy of microservices.', 'Detection involves analyzing the number of teams contributing to the code repository.', 'With the entire microservice system developed by a single team, the autonomy between individual microservices becomes limited, resulting in reduced modularity of the service.', 'Disregarding the advantages of independent development by multiple teams.', 'In an entire microservices system, a solitary team assumes the responsibility of developing and maintaining multiple microservices. This necessitates dealing with different technology stacks and business logic simultaneously, thereby introducing development challenges.', '[\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\"]', 'Team & Technology', 'Team ', 1, 0);
INSERT INTO `antipattern_info` VALUES (140, 'Too Many Standards', '[\"Excessive diversity or heterogeneity in the technologies chosen across the system\"，,\"Excessive diversity\", \"Too many technologies\"]', 'It refers to the utilization of multiple development languages and frameworks in the development of a microservice system.', 'Detection involves analyzing the dependency files to determine the framework used by each service and examining the repository to identify the use of different programming languages.', 'The adoption of multiple technologies introduces complexity to the system and adversely affects its availability. The maintainability of the system becomes more challenging as each technology stack necessitates independent maintenance and updates, including version upgrades and security vulnerability fixes. Moreover, the use of multiple technologies may impose a higher learning burden on team members, thereby reducing learnability.', 'The lack of unified technical standards and guidance for the development team.', 'The utilization of diverse data access frameworks (e.g., spring data jpa, mybatis, etc.) across the microservices system contributes to its overall complexity, without a clear justification for such a range of choices.', '[\"@article{de2021identifying,   title={Identifying architectural technical debt, principal, and interest in microservices: A multiple-case study},   author={de Toledo, Saulo S and Martini, Antonio and Sj{\\\\o}berg, Dag IK},   journal={Journal of Systems and Software},   volume={177},   pages={110968},   year={2021},   publisher={Elsevier} }\",\"@article{taibi2018definition,   title={On the definition of microservice bad smells},   author={Taibi, Davide and Lenarduzzi, Valentina},   journal={IEEE software},   volume={35},   number={3},   pages={56--62},   year={2018},   publisher={IEEE} }\",\"@article{de2022accumulation,   title={Accumulation and prioritization of architectural debt in three companies migrating to microservices},   author={De Toledo, Saulo Soares and Martini, Antonio and Nguyen, Phu H and Sj{\\\\o}berg, Dag IK},   journal={IEEE Access},   volume={10},   pages={37422--37445},   year={2022},   publisher={IEEE} }\",\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"@inproceedings{pulnil2022microservices,   title={A microservices quality model based on microservices anti-patterns},   author={Pulnil, Sermsook and Senivongse, Twittie},   booktitle={2022 19th International Joint Conference on Computer Science and Software Engineering (JCSSE)},   pages={1--6},   year={2022},   organization={IEEE} }\",\"@article{walker2020automated,   title={Automated code-smell detection in microservices through static analysis: A case study},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   journal={Applied Sciences},   volume={10},   number={21},   pages={7800},   year={2020},   publisher={MDPI} }\",\" @inproceedings{walker2021automated,   title={Automated microservice code-smell detection},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   booktitle={Information Science and Applications: Proceedings of ICISA 2020},   pages={211--221},   year={2021},   organization={Springer} }\"]', 'Team & Technology', 'Technology', 7, 0);
INSERT INTO `antipattern_info` VALUES (141, 'Inadequate Techniques Support', NULL, 'It refers to situations where optimal technology choices were not made during the development of the microservices system, and the current technology stack may struggle to handle the expanding business functionality.', 'A comprehensive evaluation of the architecture and technology choices of the microservices system is conducted to determine if there is insufficient technical support.', 'The utilization of incomplete technologies has a negative impact on the system\'s maintainability. If the current technology stack fails to meet business requirements or lacks necessary functional support, the system may not achieve its full functionality, thereby affecting its functional completeness.', 'Disregarding the advantages of independent development by multiple teams.', 'Some microservices employ relational databases (e.g., mysql) for data storage, which may encounter performance bottlenecks when dealing with high-concurrency and large-scale data operations. Consequently, the database\'s read and write operations may become sluggish, resulting in delayed system response times.', '[\"@article{de2021identifying,   title={Identifying architectural technical debt, principal, and interest in microservices: A multiple-case study},   author={de Toledo, Saulo S and Martini, Antonio and Sj{\\\\o}berg, Dag IK},   journal={Journal of Systems and Software},   volume={177},   pages={110968},   year={2021},   publisher={Elsevier} }\"]', 'Team & Technology', 'Technology', 6, 0);
INSERT INTO `antipattern_info` VALUES (142, 'Shared Libraries', '[\"Reusing third-party implementations\"，\"Misusing shared libraries\"]', 'It refers to the practice of sharing dependency libraries among different microservices. When multiple microservices rely on the same shared library, any changes made to that library can potentially impact all the microservices utilizing it.', 'Determination is made by analysing the dependency files of each service.', 'If multiple microservices are dependent on the same shared library, any modifications made to the library will necessitate changes in multiple microservices. This results in increased coupling within the system, undermining its modularity, and adversely affecting its maintainability, resilience, and installability.', 'Failure to extract business logic associated with shared libraries into a public service.', 'Consider an e-commerce platform consisting of two microservices: an order service and a payment service. The development team made the decision to employ a shared library to handle date and time-related operations, such as date formatting and time zone conversion. They selected a robust library capable of managing both date and time functionalities. As a result, this date-time processing library was integrated into both the order service and the payment service. However, over time, the team realized that only a fraction of the library\'s functionality was actually being utilized, and updates to the library were becoming sluggish. Further analysis revealed that the shared library was excessively large and complex for the specific requirements of the microservices. Moreover, the infrequent updates to the library hindered the timely adoption of new features and the resolution of vulnerabilities by the microservices.', '[\"@article{de2021identifying,   title={Identifying architectural technical debt, principal, and interest in microservices: A multiple-case study},   author={de Toledo, Saulo S and Martini, Antonio and Sj{\\\\o}berg, Dag IK},   journal={Journal of Systems and Software},   volume={177},   pages={110968},   year={2021},   publisher={Elsevier} }\",\"@article{taibi2018definition,   title={On the definition of microservice bad smells},   author={Taibi, Davide and Lenarduzzi, Valentina},   journal={IEEE software},   volume={35},   number={3},   pages={56--62},   year={2018},   publisher={IEEE} }\",\"@article{de2022accumulation,   title={Accumulation and prioritization of architectural debt in three companies migrating to microservices},   author={De Toledo, Saulo Soares and Martini, Antonio and Nguyen, Phu H and Sj{\\\\o}berg, Dag IK},   journal={IEEE Access},   volume={10},   pages={37422--37445},   year={2022},   publisher={IEEE} }\",\"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\",\"@inproceedings{pulnil2022microservices,   title={A microservices quality model based on microservices anti-patterns},   author={Pulnil, Sermsook and Senivongse, Twittie},   booktitle={2022 19th International Joint Conference on Computer Science and Software Engineering (JCSSE)},   pages={1--6},   year={2022},   organization={IEEE} }\",\"@article{walker2020automated,   title={Automated code-smell detection in microservices through static analysis: A case study},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   journal={Applied Sciences},   volume={10},   number={21},   pages={7800},   year={2020},   publisher={MDPI} }\",\"@inproceedings{walker2021automated,   title={Automated microservice code-smell detection},   author={Walker, Andrew and Das, Dipta and Cerny, Tomas},   booktitle={Information Science and Applications: Proceedings of ICISA 2020},   pages={211--221},   year={2021},   organization={Springer} }\",\"@inproceedings{schirgi2021quality,   title={Quality assurance for microservice architectures},   author={Schirgi, Thomas and Brenner, Eugen},   booktitle={2021 IEEE 12th International Conference on Software Engineering and Service Science (ICSESS)},   pages={76--80},   year={2021},   organization={IEEE} }\"]', 'Team & Technology', 'Technology', 7, 0);
INSERT INTO `antipattern_info` VALUES (143, 'Focus On Latest Technologies', '[\"Lust\",\"Too new technology\"]', 'It refers to the tendency of development teams to prioritize the adoption of the latest technologies and tools, disregarding the system requirements and maintainability.', 'Investigate and analyse the technology stack used in the system and then make further determinations.', 'The presence of numerous security concerns, potential flaws, and compromised fault tolerance is evident. Limited availability of research materials, high costs associated with hands-on implementation, and unnecessary complexity further exacerbate the situation, impacting system adaptability and subsequent maintainability. Additionally, new technologies often entail a steep learning curve. Frequent introduction of new technologies can result in considerable time investment for teams, impeding their learning and adaptability efforts, consequently diminishing user learnability.', 'The development team ignored the actual needs of the system and the soundness of the technology choices.', 'Suppose a team tasked with developing a user management microservice for an online social media platform. During the process of selecting technologies, they come across a recently introduced and extensively discussed authentication and authorization framework that asserts its possession of advanced security features and adaptable permission management capabilities. However, this framework is still in its early stages and has not undergone widespread usage or practical validation. Despite its claims of advanced security features, it suffers from limited documentation and support resources. Furthermore, it lacks seamless integration and compatibility with the existing components already employed by the team.', '[\"@article{taibi2018definition,   title={On the definition of microservice bad smells},   author={Taibi, Davide and Lenarduzzi, Valentina},   journal={IEEE software},   volume={35},   number={3},   pages={56--62},   year={2018},   publisher={IEEE} }\", \"@article{taibi2020microservices,   title={Microservices anti-patterns: A taxonomy},   author={Taibi, Davide and Lenarduzzi, Valentina and Pahl, Claus},   journal={Microservices: Science and Engineering},   pages={111--128},   year={2020},   publisher={Springer} }\", \"@inproceedings{schirgi2021quality,   title={Quality assurance for microservice architectures},   author={Schirgi, Thomas and Brenner, Eugen},   booktitle={2021 IEEE 12th International Conference on Software Engineering and Service Science (ICSESS)},   pages={76--80},   year={2021},   organization={IEEE} }\"]', 'Team & Technology', 'Technology', 14, 0);
