INSERT INTO `antipattern_type` VALUES (22, 'Internal Design', 'This catalogue refers to the presence of poor or unreasonable patterns or practices within the design of services in a microservices system. It primarily manifests in three aspects: API design, internal method design, and granularity design.', NULL, '1', 0);
INSERT INTO `antipattern_type` VALUES (23, 'API design', 'API is the interface exposed by a service to the external environment, which defines the functionality and interaction methods of the service. API design smells refer to the presence of irrational or inconsistent patterns in the design of service APIs, which may make the services difficult to use, understand, and extend.', 'Internal Design', '1-1', 0);
INSERT INTO `antipattern_type` VALUES (24, 'Method Design', 'It pertains to issues in the design of internal methods within services. It is primarily characterized by methods that undertake too few responsibilities or lack focus on the main task objectives.', 'Internal Design', '1-2', 0);
INSERT INTO `antipattern_type` VALUES (25, 'Granularity Design', 'Granularity refers to the extent to which a system is divided into different service units. Granularity design smells in the context of microservices architecture point to issues in the selection of service granularity. For example, when services become excessively large, have unreasonable functional aggregations, and exhibit high coupling between internal modules, they become difficult to maintain and test.', 'Internal Design', '1-3', 0);
INSERT INTO `antipattern_type` VALUES (26, 'Communication & Interaction', 'This catalogue refers to the presence of poor patterns or practices in the communication and interaction between services within a microservices system. These issues may lead to problems related to system reliability, performance, and maintainability.', NULL, '2', 0);
INSERT INTO `antipattern_type` VALUES (27, 'Communication', 'This catalogue involves issues related to message passing and communication between services. It includes low traceability of messages, unreasonable design of communication endpoints and communication layers, and lack of unified communication standards.', 'Communication & Interaction', '2-1', 0);
INSERT INTO `antipattern_type` VALUES (28, 'Interaction', 'This catalogue involves problems with the way and mode of interaction between services. It includes problems such as unstable service interactions, consistency problems between interactions, and poorly designed service call chains.', 'Communication & Interaction', '2-2', 0);
INSERT INTO `antipattern_type` VALUES (29, 'Structure & Infrastructure', 'This catalogue refers to the presence of poor patterns or unreasonable decisions in the design and implementation of service architectures. It primarily includes issues such as unnecessary configurations and inadequate infrastructure, which may result in increased system complexity, reduced maintainability, and degraded performance.', NULL, '3', 0);
INSERT INTO `antipattern_type` VALUES (30, 'Infrastructure', 'This catalogue refers to problems or poor decisions related to the infrastructure aspect of service architectures. It mainly encompasses issues such as a lack of API gateways and failure to utilize service discovery components.', 'Structure & Infrastructure', '3-1', 0);
INSERT INTO `antipattern_type` VALUES (31, 'Structure', 'This catalogue refers to problems or poor patterns in the topology aspect of service architectures. It primarily includes issues such as unreasonable and unstable dependencies between services.', 'Structure & Infrastructure', '3-2', 0);
INSERT INTO `antipattern_type` VALUES (32, 'Decomposition', 'This catalogue refers to the presence of problems or poor patterns in the process of service decomposition. It primarily includes issues such as unreasonable service decomposition, scattered functionality, and high service duplication, which increase the overall complexity of the system and make it difficult to maintain and scale.', NULL, '4', 0);
INSERT INTO `antipattern_type` VALUES (33, 'Functionality', 'It refers to the problems or bad practices brought about by the process of function splitting. It mainly includes problems such as greed, overlap, and fragmentation.', 'Decomposition ', '4-1', 0);
INSERT INTO `antipattern_type` VALUES (34, 'Service Data Management', 'This catalogue refers to problems or poor patterns that arise during service decomposition and data management processes. They mainly involve aspects such as data coupling between services, data sharing, and data access methods.', 'Decomposition ', '4-2', 0);
INSERT INTO `antipattern_type` VALUES (35, 'Security', 'This catalogue refers to the presence of security-related issues or poor practices in service architectures. It primarily includes data and communication security, as well as authentication and authorization security. These smells can lead to risks such as data leaks, system attacks, and unauthorized access.', '', '5', 0);
INSERT INTO `antipattern_type` VALUES (36, 'Data and Communication', 'This catalogue refers to  the methods of handling and transmitting data within services, as well as the associated security concerns. It mainly involves aspects such as communication data encryption and key management.', 'Security', '5-1', 0);
INSERT INTO `antipattern_type` VALUES (37, 'Authentication and Authorization', 'This catalogue focuses on the authentication and access control issues within services, ensuring that only legitimate users or services can access and perform specific operations.', 'Security', '5-2', 0);
INSERT INTO `antipattern_type` VALUES (38, 'Lifecycle Management', 'This catalogue refers to problems or poor patterns throughout the entire lifecycle of a service, encompassing the planning, development, deployment, and maintenance phases. These bad practices can lead to resource wastage, quality issues, and ultimately impact the reliability and stability of the service.', NULL, '6', 0);
INSERT INTO `antipattern_type` VALUES (39, 'Migration', 'It refers to the problems or unfavorable practices that arise during the service migration process. It primarily includes issues related to migration strategies and the selection of specific migration content.', 'Lifecycle Management', '6-1', 0);
INSERT INTO `antipattern_type` VALUES (40, 'Deployment', 'It refers to the problems or unfavorable practices that occur during the service deployment process. This encompasses issues such as the adoption of automated deployment workflows, system configuration, and log management. ', 'Lifecycle Management', '6-2', 0);
INSERT INTO `antipattern_type` VALUES (41, 'Operations ', 'It refers to the problems or unfavorable practices that surface during the service operations phase. This includes aspects such as monitoring, fault handling, and integration and deployment approachs.', 'Lifecycle Management', '6-3', 0);
INSERT INTO `antipattern_type` VALUES (42, 'Team & Technology', ' It refers to the problems or unfavorable practices that exist within  organizations or teams, such as inadequate team structure and unreasonable technology stack choices. These issues can have a negative impact on work efficiency, collaboration, and innovation capabilities.', NULL, '7', 0);
INSERT INTO `antipattern_type` VALUES (43, 'Team ', 'It refers to problems or bad practices brought about by the process of dividing team responsibilities. It mainly includes problems related to improper division of duties and too many duties.', 'Team & Technology', '7-1', 0);
INSERT INTO `antipattern_type` VALUES (44, 'Technology', 'It refers to the problems or unfavorable practices that may arise during the formulation and execution of service technology strategies. It includes issues related to technical standards, technology selection, and technical dependencies. The presence of these smells can lead to the accumulation of technical debt.', 'Team & Technology', '7-2', 0);
